window.ETSDATA=window.ETSDATA||{};window.ETSDATA[30]={"lc":{"p1":[{"n":1,"opts":["A man is preparing some food.","A man is serving a dish.","A man is removing a hat.","A man is taking an order."],"vi":["Một người đàn ông đang chuẩn bị đồ ăn.","Một người đàn ông đang dọn món ăn ra.","Một người đàn ông đang cởi mũ.","Một người đàn ông đang ghi món khách gọi."],"ans":"A","xp":"Tranh: đầu bếp đứng nấu ăn trong bếp → (A). Ông vẫn đội mũ (C sai), không có khách (B)(D sai).","a":"XC-T10-01.mp3","img":"q1.jpg"},{"n":2,"opts":["They are shaking hands.","A window has been left open.","They are facing each other.","A cup is being placed on a table."],"vi":["Họ đang bắt tay.","Một cửa sổ đang để mở.","Họ đang ngồi đối diện nhau.","Một cái cốc đang được đặt lên bàn."],"ans":"C","xp":"Tranh: hai người đàn ông ngồi đối diện nhau qua bàn → (C). Họ không bắt tay; cốc đã nằm trên bàn, không ai đang đặt.","a":"XC-T10-02.mp3","img":"q2.jpg"},{"n":3,"opts":["A woman is kneeling down on a floor.","A man is trying on a pair of shoes.","An item is being put into a box.","Some merchandise is displayed on shelves."],"vi":["Một người phụ nữ đang quỳ trên sàn.","Một người đàn ông đang thử giày.","Một món đồ đang được bỏ vào hộp.","Một số hàng hóa được bày trên kệ."],"ans":"D","xp":"Tranh: cửa hàng giày, nhiều đôi giày bày trên kệ → (D). Người đàn ông đang ngồi, không thấy đang xỏ giày; người phụ nữ đứng chứ không quỳ.","a":"XC-T10-03.mp3","img":"q3.jpg"},{"n":4,"opts":["One of the women is talking on the phone.","Computer monitors are set up side by side.","One of the men is writing on a form.","A suitcase is being loaded onto a cart."],"vi":["Một người phụ nữ đang nói chuyện điện thoại.","Các màn hình máy tính được đặt cạnh nhau.","Một người đàn ông đang viết vào mẫu đơn.","Một vali đang được chất lên xe đẩy."],"ans":"B","xp":"Tranh: quầy làm thủ tục, các màn hình máy tính đặt cạnh nhau → (B).","a":"XC-T10-04.mp3","img":"q4.jpg"},{"n":5,"opts":["Some benches are being repaired.","People are watching a street parade.","There are lampposts along both sides of a street.","Some light bulbs are being replaced."],"vi":["Một số ghế dài đang được sửa.","Mọi người đang xem diễu hành trên phố.","Có cột đèn dọc hai bên đường.","Một số bóng đèn đang được thay."],"ans":"C","xp":"Tranh: con đường có hàng cột đèn ở hai bên → (C). Không ai sửa ghế hay thay bóng đèn, không có diễu hành.","a":"XC-T10-05.mp3","img":"q5.jpg"},{"n":6,"opts":["A trail leads to a village.","A bridge crosses over a river.","Some trees are being watered.","A boat is tied to a pier."],"vi":["Một con đường mòn dẫn đến ngôi làng.","Một cây cầu bắc qua sông.","Một số cây đang được tưới.","Một chiếc thuyền được buộc vào bến."],"ans":"B","xp":"Tranh: dòng sông, phía xa có cây cầu bắc ngang → (B). Không có làng, thuyền hay người tưới cây.","a":"XC-T10-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"Could you bring some menus to table seven?","qvi":"Bạn mang giúp vài cuốn thực đơn đến bàn số 7 được không?","opts":["Sure, how many?","A regular customer.","My favorite dish."],"vi":["Được chứ, bao nhiêu cuốn?","Một khách quen.","Món tôi thích nhất."],"ans":"A","xp":"Lời nhờ → đồng ý và hỏi lại: (A). (B)(C) liên tưởng nhà hàng.","a":"XC-T10-07.mp3"},{"n":8,"q":"When will the itinerary be finalized?","qvi":"Khi nào lịch trình chuyến đi được chốt?","opts":["At the end of the month.","We're traveling to Tokyo.","Jill from human resources."],"vi":["Vào cuối tháng.","Chúng tôi sẽ đi Tokyo.","Jill ở phòng nhân sự."],"ans":"A","xp":"Câu hỏi When → (A). (B) liên tưởng itinerary – du lịch, (C) trả lời Who.","a":"XC-T10-08.mp3"},{"n":9,"q":"Which sofa did Vanessa decide to buy?","qvi":"Vanessa quyết định mua ghế sô pha nào?","opts":["The leather one.","I doubt that.","For her new apartment."],"vi":["Cái bằng da.","Tôi nghi ngờ điều đó.","Cho căn hộ mới của cô ấy."],"ans":"A","xp":"Câu hỏi Which → (A) 'Cái bằng da' (one = sofa). (C) trả lời mục đích.","a":"XC-T10-09.mp3"},{"n":10,"q":"Isn't Mark giving the keynote address?","qvi":"Không phải Mark sẽ có bài phát biểu chính sao?","opts":["No, it was offered to Mr. Carver.","You can use my spare keys.","It's printed on the business card."],"vi":["Không, việc đó được giao cho ông Carver.","Bạn có thể dùng chìa khóa dự phòng của tôi.","Nó được in trên danh thiếp."],"ans":"A","xp":"Câu hỏi phủ định → (A). (B) lặp âm keynote/keys, (C) address nghĩa 'địa chỉ' – danh thiếp.","a":"XC-T10-10.mp3"},{"n":11,"q":"Where are the blueprints for the city's fitness center?","qvi":"Bản thiết kế trung tâm thể dục của thành phố ở đâu?","opts":["About ten thousand square feet.","The manager was reviewing them earlier.","The downtown office is nearby."],"vi":["Khoảng mười nghìn feet vuông.","Lúc nãy quản lý đang xem chúng.","Văn phòng trung tâm ở gần đây."],"ans":"B","xp":"Câu hỏi Where → trả lời gián tiếp (B) 'Quản lý đang xem' (chắc ở chỗ quản lý). (A) liên tưởng diện tích.","a":"XC-T10-11.mp3"},{"n":12,"q":"Let me carry some of those crates for you.","qvi":"Để tôi mang giúp bạn mấy thùng đó.","opts":["What does the label say?","We don't carry that brand.","Thanks, but they're not heavy."],"vi":["Nhãn ghi gì vậy?","Chúng tôi không bán nhãn hiệu đó.","Cảm ơn, nhưng chúng không nặng."],"ans":"C","xp":"Đề nghị giúp → từ chối lịch sự: (C). (B) lặp từ carry (nghĩa 'có bán').","a":"XC-T10-12.mp3"},{"n":13,"q":"Why do I have to pay an additional fee?","qvi":"Sao tôi phải trả thêm phí?","opts":["No, there aren't any left.","By credit card or cash.","Because your luggage is overweight."],"vi":["Không, không còn cái nào.","Bằng thẻ tín dụng hoặc tiền mặt.","Vì hành lý của bạn quá cân."],"ans":"C","xp":"Câu hỏi Why → (C) 'Because...'. (B) trả lời How (cách trả), (A) Wh- không trả lời No.","a":"XC-T10-13.mp3"},{"n":14,"q":"What style do you want for the new uniforms?","qvi":"Bạn muốn kiểu nào cho đồng phục mới?","opts":["You must wear it while on duty.","I want them to be machine-washable.","Yes, from a discount supplier."],"vi":["Bạn phải mặc nó khi làm việc.","Tôi muốn loại giặt máy được.","Vâng, từ nhà cung cấp giá rẻ."],"ans":"B","xp":"Câu hỏi What style → (B) nêu yêu cầu cho đồng phục. (A) liên tưởng đồng phục, (C) Wh- không trả lời Yes.","a":"XC-T10-14.mp3"},{"n":15,"q":"How can I transfer a call to another employee?","qvi":"Làm sao để chuyển cuộc gọi cho nhân viên khác?","opts":["She transferred to our head office.","I'm sorry I didn't call you back.","Hold down this button for three seconds."],"vi":["Cô ấy đã chuyển lên trụ sở chính.","Xin lỗi tôi đã không gọi lại cho bạn.","Giữ nút này trong ba giây."],"ans":"C","xp":"Câu hỏi How (cách làm) → (C). (A) lặp từ transfer, (B) lặp từ call.","a":"XC-T10-15.mp3"},{"n":16,"q":"Are there any more manuscripts for me to check?","qvi":"Còn bản thảo nào cho tôi kiểm tra không?","opts":["Please e-mail it to me.","They should be on your desk.","You can check out anytime."],"vi":["Hãy e-mail nó cho tôi.","Chắc chúng ở trên bàn bạn.","Bạn có thể trả phòng bất cứ lúc nào."],"ans":"B","xp":"Hỏi còn bản thảo không → (B) 'Chắc ở trên bàn bạn'. (C) lặp từ check.","a":"XC-T10-16.mp3"},{"n":17,"q":"Where can I find the main laboratory?","qvi":"Phòng thí nghiệm chính ở đâu?","opts":["The technicians have made a breakthrough.","He's there or in the research library.","Down the hall and to the right."],"vi":["Các kỹ thuật viên đã có đột phá.","Anh ấy ở đó hoặc ở thư viện nghiên cứu.","Đi hết hành lang rồi rẽ phải."],"ans":"C","xp":"Câu hỏi Where → chỉ đường: (C). (B) 'He' không rõ là ai.","a":"XC-T10-17.mp3"},{"n":18,"q":"Who gave you the go-ahead for a new carpet?","qvi":"Ai cho phép bạn thay thảm mới?","opts":["A couple of days ago.","I think it looks much better now.","Someone on the finance team."],"vi":["Vài ngày trước.","Tôi nghĩ giờ trông đẹp hơn nhiều.","Một người bên nhóm tài chính."],"ans":"C","xp":"Câu hỏi Who → (C). (A) trả lời When.","a":"XC-T10-18.mp3"},{"n":19,"q":"Don't we have to confirm the car rental?","qvi":"Chúng ta không phải xác nhận việc thuê xe sao?","opts":["We rented a large ballroom.","Yes, I'll take care of it.","I parked on the street."],"vi":["Chúng tôi đã thuê một phòng tiệc lớn.","Có, tôi sẽ lo việc đó.","Tôi đỗ xe trên đường."],"ans":"B","xp":"Câu hỏi phủ định → (B) 'Có, tôi sẽ lo'. (A) lặp âm rental/rented, (C) liên tưởng xe.","a":"XC-T10-19.mp3"},{"n":20,"q":"Would you like me to introduce you to some of the charity's board members?","qvi":"Bạn có muốn tôi giới thiệu bạn với vài thành viên ban quản trị của tổ chức từ thiện không?","opts":["Sure, I'm very anxious to meet them.","Any donations are always welcome.","No, only to the store members."],"vi":["Có chứ, tôi rất mong được gặp họ.","Mọi khoản quyên góp luôn được chào đón.","Không, chỉ cho thành viên cửa hàng."],"ans":"A","xp":"Lời đề nghị → nhận lời (A). (B) liên tưởng charity – quyên góp, (C) lặp từ members.","a":"XC-T10-20.mp3"},{"n":21,"q":"Are you attending the fireworks show or staying in your hotel room?","qvi":"Bạn đi xem pháo hoa hay ở trong phòng khách sạn?","opts":["Make sure you bring some snacks.","There isn't an entrance fee.","I try to avoid loud noises."],"vi":["Nhớ mang đồ ăn vặt nhé.","Không mất phí vào cửa.","Tôi cố tránh tiếng ồn lớn."],"ans":"C","xp":"Câu hỏi lựa chọn → (C) 'Tôi tránh tiếng ồn' = ở lại khách sạn. (A)(B) liên tưởng buổi xem pháo hoa.","a":"XC-T10-21.mp3"},{"n":22,"q":"The shelf of wool sweaters is almost empty.","qvi":"Kệ áo len gần hết hàng rồi.","opts":["The weather forecast calls for sunshine.","There's more merchandise in the stockroom.","Do you mind refilling my cup?"],"vi":["Dự báo thời tiết là trời nắng.","Trong kho còn hàng.","Bạn rót thêm cho tôi được không?"],"ans":"B","xp":"Báo hết hàng → giải pháp: (B) 'Trong kho còn hàng'. (A) lặp âm sweaters/weather, (C) liên tưởng empty – refill.","a":"XC-T10-22.mp3"},{"n":23,"q":"Aren't you headed to the Internet café?","qvi":"Không phải bạn định đến quán cà phê Internet sao?","opts":["Amanda doesn't drink coffee.","I can access the Internet with my mobile phone.","Try restarting your computer."],"vi":["Amanda không uống cà phê.","Tôi có thể vào mạng bằng điện thoại.","Hãy thử khởi động lại máy tính."],"ans":"B","xp":"Trả lời gián tiếp 'không' → (B) 'Tôi vào mạng bằng điện thoại được' (nên không cần đến quán). (A) lặp âm café/coffee.","a":"XC-T10-23.mp3"},{"n":24,"q":"When will the driveway of the apartment building be resurfaced?","qvi":"Khi nào lối xe vào tòa chung cư được làm lại mặt đường?","opts":["I heard a crew is coming tomorrow.","You can drive my car.","A spacious two-bedroom unit."],"vi":["Tôi nghe nói mai đội thợ sẽ đến.","Bạn có thể lái xe của tôi.","Một căn hai phòng ngủ rộng rãi."],"ans":"A","xp":"Câu hỏi When → (A). (B) lặp âm driveway/drive, (C) liên tưởng căn hộ.","a":"XC-T10-24.mp3"},{"n":25,"q":"Who's developing the emergency evacuation plan?","qvi":"Ai đang lập kế hoạch sơ tán khẩn cấp?","opts":["Probably the building supervisor.","I'm glad everyone is okay.","That's what we were expecting."],"vi":["Có lẽ là người quản lý tòa nhà.","Tôi mừng là mọi người đều ổn.","Đó là điều chúng tôi đã dự đoán."],"ans":"A","xp":"Câu hỏi Who → (A). (B) liên tưởng khẩn cấp.","a":"XC-T10-25.mp3"},{"n":26,"q":"Weren't you supposed to go to the convention this weekend?","qvi":"Không phải cuối tuần này bạn phải đi hội nghị sao?","opts":["At the Marksburg Convention Center?","An informative talk?","It's only for managers."],"vi":["Ở trung tâm hội nghị Marksburg à?","Một bài nói nhiều thông tin à?","Nó chỉ dành cho quản lý."],"ans":"C","xp":"Trả lời gián tiếp 'không' → (C) 'Chỉ dành cho quản lý' (tôi không phải quản lý). (A) lặp từ convention.","a":"XC-T10-26.mp3"},{"n":27,"q":"Don't shipments arrive within three business days?","qvi":"Không phải hàng sẽ đến trong vòng ba ngày làm việc sao?","opts":["That sounds perfect.","Actually, I work full-time.","Not those from overseas."],"vi":["Nghe tuyệt đấy.","Thật ra tôi làm toàn thời gian.","Hàng từ nước ngoài thì không."],"ans":"C","xp":"Câu hỏi phủ định → (C) 'Hàng từ nước ngoài thì không'. (B) liên tưởng business days – công việc.","a":"XC-T10-27.mp3"},{"n":28,"q":"Can you write a review for the movie's new sequel?","qvi":"Bạn viết bài đánh giá phần tiếp theo của bộ phim được không?","opts":["The view is better in the front.","Right, I'm moving next week.","I'm watching it tonight."],"vi":["Ngồi phía trước nhìn rõ hơn.","Đúng, tuần sau tôi chuyển nhà.","Tối nay tôi sẽ xem nó."],"ans":"C","xp":"Lời nhờ → (C) 'Tối nay tôi xem' (xem xong sẽ viết). (A) lặp âm review/view, (B) lặp âm movie/moving.","a":"XC-T10-28.mp3"},{"n":29,"q":"How long did the negotiations with Vince Manufacturing take?","qvi":"Đàm phán với Vince Manufacturing mất bao lâu?","opts":["They accepted our first offer.","No, we will bring extras next time.","Regulations have recently changed."],"vi":["Họ chấp nhận ngay đề nghị đầu tiên.","Không, lần sau chúng tôi sẽ mang thêm.","Quy định vừa thay đổi."],"ans":"A","xp":"Câu hỏi How long → trả lời gián tiếp (A) 'Họ nhận ngay đề nghị đầu' = rất nhanh. (B) Wh- không trả lời No.","a":"XC-T10-29.mp3"},{"n":30,"q":"The shareholders have requested a more detailed report.","qvi":"Cổ đông yêu cầu một báo cáo chi tiết hơn.","opts":["But our workload is already too much.","They can be viewed through our secure Web site.","I don't mind sharing my office with you."],"vi":["Nhưng khối lượng việc của chúng ta đã quá nhiều rồi.","Có thể xem chúng qua trang web bảo mật.","Tôi không ngại dùng chung văn phòng với bạn."],"ans":"A","xp":"Đáp lại thông tin bằng lời phàn nàn: (A). (C) lặp âm shareholders/sharing.","a":"XC-T10-30.mp3"},{"n":31,"q":"This shuttle ride from the airport takes about twenty minutes, doesn't it?","qvi":"Chuyến xe đưa đón từ sân bay mất khoảng 20 phút, phải không?","opts":["In that case, I'll fly first class.","It depends on the road conditions.","No, I prefer to take the subway."],"vi":["Vậy thì tôi sẽ bay hạng nhất.","Còn tùy tình hình đường sá.","Không, tôi thích đi tàu điện ngầm hơn."],"ans":"B","xp":"Trả lời 'còn tùy' → (B). (A) liên tưởng sân bay.","a":"XC-T10-31.mp3"}],"p3":[{"ns":[32,34],"script":[["M","You've reached Aurora Dental Clinic. How may I assist you?","Phòng khám nha khoa Aurora xin nghe. Tôi giúp gì được ạ?"],["W","Hello. This is Esther Kim. I called a few days ago to book an appointment for January 9, but I just got a message saying the appointment is on January 11. I want to make sure I have the right date.","Xin chào, tôi là Esther Kim. Vài hôm trước tôi gọi đặt lịch hẹn ngày 9 tháng 1, nhưng vừa nhận tin nhắn nói lịch hẹn là ngày 11. Tôi muốn chắc chắn ngày nào mới đúng."],["M","We do have you booked for January 9. We launched our text-alert system last week, but it has a few system errors. Sorry for the confusion.","Chị đúng là đặt lịch ngày 9. Tuần trước chúng tôi mới ra mắt hệ thống nhắn tin nhắc hẹn nhưng nó còn vài lỗi. Xin lỗi đã làm chị bối rối."],["W","No problem. I'll see you on January 9, then.","Không sao. Vậy hẹn gặp ngày 9 tháng 1."]],"qs":[{"n":32,"q":"What kind of business is the woman calling?","qvi":"Người phụ nữ gọi đến loại cơ sở nào?","opts":["A grocery store","A dental clinic","A bookstore","A hair salon"],"vi":["Cửa hàng tạp hóa","Phòng khám nha khoa","Hiệu sách","Tiệm làm tóc"],"ans":"B","xp":"'You've reached Aurora Dental Clinic' → (B)."},{"n":33,"q":"What is the purpose of the woman's call?","qvi":"Mục đích cuộc gọi của người phụ nữ là gì?","opts":["To report an address change","To inquire about opening hours","To place an order","To check an appointment time"],"vi":["Báo đổi địa chỉ","Hỏi giờ mở cửa","Đặt hàng","Kiểm tra thời gian hẹn"],"ans":"D","xp":"'I want to make sure I have the right date' (ngày hẹn) → (D)."},{"n":34,"q":"What did the business do last week?","qvi":"Tuần trước phòng khám đã làm gì?","opts":["Opened a second location","Hired some new employees","Started a text-alert service","Raised its prices"],"vi":["Mở chi nhánh thứ hai","Tuyển nhân viên mới","Bắt đầu dịch vụ nhắn tin nhắc hẹn","Tăng giá"],"ans":"C","xp":"'We launched our text-alert system last week' → (C)."}],"a":"XC-T10-32-34.mp3"},{"ns":[35,37],"script":[["M","Hello, Ms. Elder. This is Mario Cruz from Hill Havens. I met you when you test-drove one of our new Krause 20 vehicles last week, and I was wondering if you were still interested in buying one.","Chào chị Elder. Tôi là Mario Cruz ở Hill Havens. Tôi đã gặp chị khi chị lái thử một chiếc Krause 20 mới tuần trước, và tôi muốn hỏi chị còn muốn mua không."],["W","Well, I'm not sure yet. I know that that vehicle has excellent safety ratings and gets good gas mileage. However, the size of the trunk was about half what I was expecting. It wouldn't be good for hauling a lot of things.","À, tôi chưa chắc. Tôi biết xe đó được đánh giá an toàn rất cao và tiết kiệm xăng. Nhưng cốp xe chỉ bằng khoảng một nửa so với tôi nghĩ. Không tiện để chở nhiều đồ."],["M","Well, that manufacturer makes a slightly larger model. I'll mail a catalog to the address you gave me so that you can check out the details. And please feel free to stop by again.","Hãng đó có một mẫu lớn hơn một chút. Tôi sẽ gửi danh mục sản phẩm đến địa chỉ chị đã cho để chị xem chi tiết. Và chị cứ ghé lại bất cứ lúc nào."]],"qs":[{"n":35,"q":"Who most likely is the man?","qvi":"Người đàn ông nhiều khả năng là ai?","opts":["A car salesperson","A real estate agent","A computer store manager","A delivery driver"],"vi":["Nhân viên bán ô tô","Môi giới bất động sản","Quản lý cửa hàng máy tính","Tài xế giao hàng"],"ans":"A","xp":"'when you test-drove one of our new Krause 20 vehicles... still interested in buying one' → (A)."},{"n":36,"q":"According to the woman, what is the problem?","qvi":"Theo người phụ nữ, vấn đề là gì?","opts":["A price exceeded a budget.","A storage space is too small.","A guarantee is not long enough.","A color is too dark."],"vi":["Giá vượt ngân sách.","Chỗ chứa đồ quá nhỏ.","Bảo hành không đủ dài.","Màu quá tối."],"ans":"B","xp":"'the size of the trunk was about half what I was expecting' → cốp xe = chỗ chứa đồ quá nhỏ → (B)."},{"n":37,"q":"What does the man say he will do?","qvi":"Người đàn ông nói sẽ làm gì?","opts":["Adjust a price","Visit the woman","Send a catalog","Make a repair"],"vi":["Điều chỉnh giá","Đến gặp người phụ nữ","Gửi danh mục sản phẩm","Sửa chữa"],"ans":"C","xp":"'I'll mail a catalog to the address you gave me' → (C)."}],"a":"XC-T10-35-37.mp3"},{"ns":[38,40],"script":[["W","Hi, James. Are you free to work on February 5? There's a fundraiser for Livonia Consulting, and we could use your help.","Chào James. Ngày 5 tháng 2 anh rảnh đi làm không? Có buổi gây quỹ cho Livonia Consulting và chúng tôi cần anh giúp."],["M","Sure. Do you need extra people to serve the food?","Được. Chị cần thêm người phục vụ đồ ăn à?"],["W","Actually, I'd like you to help out before the party begins. You recently took a training course on decorating for large-scale events, right?","Thật ra tôi muốn anh giúp trước khi tiệc bắt đầu. Anh mới học khóa trang trí cho sự kiện lớn, phải không?"],["M","That's right. I'd love the opportunity to practice what I learned.","Đúng vậy. Tôi rất muốn có dịp thực hành những gì đã học."],["W","Wonderful. Here's Livonia Consulting's number, so you can find out what colors or styles they have in mind.","Tuyệt. Đây là số điện thoại của Livonia Consulting để anh hỏi xem họ muốn màu sắc hay phong cách nào."]],"qs":[{"n":38,"q":"What is scheduled for February 5?","qvi":"Ngày 5 tháng 2 có sự kiện gì?","opts":["An anniversary party","A fundraising event","A retirement dinner","An academic lecture"],"vi":["Tiệc kỷ niệm","Sự kiện gây quỹ","Tiệc nghỉ hưu","Bài giảng học thuật"],"ans":"B","xp":"'February 5? There's a fundraiser for Livonia Consulting' → (B)."},{"n":39,"q":"What has the man been trained to do?","qvi":"Người đàn ông đã được đào tạo làm gì?","opts":["Cook healthy meals","Decorate rooms","Set up sound equipment","Design invitations"],"vi":["Nấu món ăn lành mạnh","Trang trí phòng","Lắp thiết bị âm thanh","Thiết kế thiệp mời"],"ans":"B","xp":"'You recently took a training course on decorating for large-scale events, right?' – 'That's right' → (B)."},{"n":40,"q":"What will the man probably do next?","qvi":"Người đàn ông có lẽ sẽ làm gì tiếp theo?","opts":["Sample some dishes","Contact a client","Select a supplier","Attend a meeting"],"vi":["Nếm thử món ăn","Liên hệ khách hàng","Chọn nhà cung cấp","Dự họp"],"ans":"B","xp":"'Here's Livonia Consulting's number, so you can find out what colors or styles they have in mind' → gọi cho khách hàng → (B)."}],"a":"XC-T10-38-40.mp3"},{"ns":[41,43],"script":[["W","Charlie, I'll be out of the office after lunch. I'm going to the manufacturing conference at Ashmore Plaza.","Charlie, sau bữa trưa tôi sẽ ra ngoài. Tôi đi hội nghị ngành sản xuất ở Ashmore Plaza."],["M","Oh, that's right. You're giving a presentation there. You must be feeling anxious about it.","À đúng rồi. Chị thuyết trình ở đó mà. Chắc chị hồi hộp lắm."],["W","Well, I did it last year.","À, năm ngoái tôi làm rồi."],["M","Oh, that's good. I hope you generate a lot of interest in our business.","Ồ, vậy thì tốt. Mong chị thu hút được nhiều sự quan tâm cho công ty mình."],["W","Me too. My goal is to get contact details from at least thirty new clients. I'll e-mail you to let you know whether or not I achieved that.","Tôi cũng mong vậy. Mục tiêu của tôi là lấy được thông tin liên lạc của ít nhất 30 khách hàng mới. Tôi sẽ e-mail báo anh xem có đạt được không."]],"qs":[{"n":41,"q":"Why will the woman be unavailable this afternoon?","qvi":"Vì sao chiều nay người phụ nữ không có mặt?","opts":["She will prepare for a proposal.","She will attend an industry conference.","She will visit a client's office.","She will lead a training session."],"vi":["Cô chuẩn bị đề xuất.","Cô dự hội nghị ngành.","Cô đến văn phòng khách hàng.","Cô hướng dẫn buổi đào tạo."],"ans":"B","xp":"'I'm going to the manufacturing conference at Ashmore Plaza' → (B)."},{"n":42,"q":"What does the woman mean when she says, \"I did it last year\"?","qvi":"Người phụ nữ có ý gì khi nói \"năm ngoái tôi làm rồi\"?","opts":["She can give the man some advice.","She needs to update some information.","She is not nervous about a talk.","She wants a task to be reassigned."],"vi":["Cô có thể khuyên người đàn ông.","Cô cần cập nhật thông tin.","Cô không lo lắng về bài thuyết trình.","Cô muốn giao việc cho người khác."],"ans":"C","xp":"Ông nói 'You must be feeling anxious'; cô đáp năm ngoái đã thuyết trình rồi → cô không lo → (C)."},{"n":43,"q":"Why will the woman e-mail the man?","qvi":"Vì sao người phụ nữ sẽ e-mail cho người đàn ông?","opts":["To give driving directions","To report a result","To extend an invitation","To request more supplies"],"vi":["Để chỉ đường","Để báo kết quả","Để mời","Để xin thêm vật dụng"],"ans":"B","xp":"'I'll e-mail you to let you know whether or not I achieved that' → báo kết quả → (B)."}],"a":"XC-T10-41-43.mp3"},{"ns":[44,46],"script":[["W","Trent, we're expecting a lot of visitors at the reserve today. It's the launch of our new smartphone app that shows all of our hiking trails.","Trent, hôm nay khu bảo tồn sẽ có nhiều khách. Hôm nay ra mắt ứng dụng điện thoại mới hiển thị tất cả đường mòn đi bộ của mình."],["M","I completely forgot about that. I was on vacation all last week, so I don't know much about it.","Tôi quên mất. Cả tuần trước tôi đi nghỉ nên không biết nhiều về nó."],["W","Well, some of the visitors might ask for your help in using the app, so you need to be familiar with the setup process. It's posted in the employee lounge.","À, có khách có thể nhờ anh hướng dẫn dùng ứng dụng, nên anh cần nắm cách cài đặt. Hướng dẫn được dán ở phòng nghỉ nhân viên."],["M","All right. I'll look that over now so I know what to do.","Được. Tôi sẽ xem ngay để biết phải làm gì."]],"qs":[{"n":44,"q":"Where do the speakers most likely work?","qvi":"Họ nhiều khả năng làm việc ở đâu?","opts":["At a sporting goods store","At a nature reserve","At a bus tour company","At a smartphone store"],"vi":["Ở cửa hàng đồ thể thao","Ở khu bảo tồn thiên nhiên","Ở công ty tour xe buýt","Ở cửa hàng điện thoại"],"ans":"B","xp":"'a lot of visitors at the reserve today... our hiking trails' → (B). (D) liên tưởng smartphone app."},{"n":45,"q":"What did the man do last week?","qvi":"Tuần trước người đàn ông đã làm gì?","opts":["He transferred to a new site.","He submitted a report.","He took some time off.","He made a recommendation."],"vi":["Chuyển đến chỗ làm mới.","Nộp báo cáo.","Nghỉ phép.","Đưa ra đề xuất."],"ans":"C","xp":"'I was on vacation all last week' → (C)."},{"n":46,"q":"What does the man plan to do next?","qvi":"Người đàn ông định làm gì tiếp theo?","opts":["Contact a manager","Confirm a schedule","Review a procedure","Lead a tour"],"vi":["Liên hệ quản lý","Xác nhận lịch","Xem lại quy trình","Dẫn tour"],"ans":"C","xp":"'the setup process. It's posted in the employee lounge' – 'I'll look that over now' → (C)."}],"a":"XC-T10-44-46.mp3"},{"ns":[47,49],"script":[["M","Caroline, we've just received approval for the new guest room management software for our resort. We're supposed to install it onto all computers in each department by the end of the day.","Caroline, mình vừa được duyệt phần mềm quản lý phòng khách mới cho khu nghỉ dưỡng. Mình phải cài nó lên tất cả máy tính ở mọi phòng ban trước cuối ngày."],["W","That doesn't give us much time to complete the work.","Vậy thì không có nhiều thời gian để làm xong."],["M","I know what you mean. Maybe we can have our employees do some of the preparations themselves.","Tôi hiểu. Có lẽ mình nhờ nhân viên tự làm một phần khâu chuẩn bị."],["W","How about releasing a memo about it? Then, people can make sure their current work is backed up in advance, which will make the process go more quickly.","Hay mình gửi thông báo nội bộ về việc này? Như vậy mọi người có thể sao lưu công việc hiện tại trước, giúp quá trình cài đặt nhanh hơn."]],"qs":[{"n":47,"q":"What kind of business do the speakers work for?","qvi":"Họ làm cho loại doanh nghiệp nào?","opts":["A conference center","A tourist resort","A computer manufacturer","A job recruitment firm"],"vi":["Trung tâm hội nghị","Khu nghỉ dưỡng du lịch","Hãng sản xuất máy tính","Công ty tuyển dụng"],"ans":"B","xp":"'guest room management software for our resort' → (B)."},{"n":48,"q":"What is the conversation mainly about?","qvi":"Cuộc hội thoại chủ yếu về điều gì?","opts":["A payment schedule","A staff retreat","A vacation policy","New software installations"],"vi":["Lịch thanh toán","Chuyến dã ngoại nhân viên","Chính sách nghỉ phép","Cài đặt phần mềm mới"],"ans":"D","xp":"'We're supposed to install it onto all computers' → (D)."},{"n":49,"q":"What does the woman suggest doing?","qvi":"Người phụ nữ đề xuất làm gì?","opts":["Changing a deadline","Holding a meeting","Sending a message","Gathering some feedback"],"vi":["Đổi hạn chót","Tổ chức họp","Gửi thông báo","Thu thập ý kiến"],"ans":"C","xp":"'How about releasing a memo about it?' → memo = tin nhắn/thông báo → (C)."}],"a":"XC-T10-47-49.mp3"},{"ns":[50,52],"script":[["M","Thank you for visiting Farland Travel.","Cảm ơn quý khách đã đến Farland Travel."],["W1","Hello. We'd like to book a flight and hotel package for a business trip to Hong Kong. I didn't expect your business to be so busy.","Xin chào. Chúng tôi muốn đặt gói vé máy bay và khách sạn cho chuyến công tác Hồng Kông. Tôi không ngờ ở đây đông vậy."],["M","Oh, that's because a representative from Bisco Luggage will demonstrate their new line of bags in about fifteen minutes, and there's a prize drawing at the end.","À, vì khoảng 15 phút nữa đại diện hãng vali Bisco sẽ giới thiệu dòng túi mới, và cuối buổi có bốc thăm trúng thưởng."],["W1","Oh, I've heard great things about their bags.","Ồ, tôi nghe nói túi của họ rất tốt."],["W2","Me too. Let's stick around.","Tôi cũng vậy. Mình ở lại xem đi."],["W1","All right, but we're supposed to have the department review meeting with Adam today.","Được, nhưng hôm nay mình có buổi họp đánh giá phòng ban với Adam."],["W2","I'm sure he wouldn't mind pushing it back an hour. Let's give him a call.","Chắc anh ấy không phiền lùi lại một tiếng đâu. Mình gọi cho anh ấy đi."]],"qs":[{"n":50,"q":"Where is the conversation most likely taking place?","qvi":"Cuộc hội thoại nhiều khả năng diễn ra ở đâu?","opts":["At a travel agency","At a restaurant","At an airport","At a clothing store"],"vi":["Ở công ty du lịch","Ở nhà hàng","Ở sân bay","Ở cửa hàng quần áo"],"ans":"A","xp":"'Thank you for visiting Farland Travel' – đặt gói vé máy bay và khách sạn → (A)."},{"n":51,"q":"What will happen in fifteen minutes?","qvi":"15 phút nữa sẽ có gì?","opts":["The business will close.","Some new equipment will be installed.","A demonstration will be given.","A tour will begin."],"vi":["Cửa hàng đóng cửa.","Lắp thiết bị mới.","Có buổi giới thiệu sản phẩm.","Tour bắt đầu."],"ans":"C","xp":"'will demonstrate their new line of bags in about fifteen minutes' → (C)."},{"n":52,"q":"Why do the women plan to call a coworker?","qvi":"Vì sao hai người phụ nữ định gọi cho đồng nghiệp?","opts":["To ask for scheduling preferences","To change a meeting time","To check on an order's status","To request a budget increase"],"vi":["Để hỏi lịch mong muốn","Để đổi giờ họp","Để kiểm tra đơn hàng","Để xin tăng ngân sách"],"ans":"B","xp":"'he wouldn't mind pushing it back an hour. Let's give him a call' → lùi giờ họp → (B)."}],"a":"XC-T10-50-52.mp3"},{"ns":[53,55],"script":[["M","Good morning. I've been sent over by Fitzburg Repairs. I'm sorry I'm a bit late. I wrote down the wrong address, so I couldn't find your building.","Chào buổi sáng. Tôi được công ty sửa chữa Fitzburg cử đến. Xin lỗi tôi đến hơi muộn. Tôi ghi sai địa chỉ nên không tìm được tòa nhà."],["W","That's fine. I called you because the window in our employee lounge is stuck open. The weather is really cold today, so we want to resolve this issue as soon as possible.","Không sao. Tôi gọi anh vì cửa sổ ở phòng nghỉ nhân viên bị kẹt không đóng được. Hôm nay trời rất lạnh nên chúng tôi muốn xử lý càng sớm càng tốt."],["M","All right. I'll take a look at it. Are there any activities scheduled to take place in that room?","Được. Tôi sẽ xem. Phòng đó có hoạt động nào được lên lịch không?"],["W","I'm planning to give a tour of our building to our new employees at eleven o'clock, but I can just skip that room if you're still working.","Tôi định dẫn nhân viên mới đi tham quan tòa nhà lúc 11 giờ, nhưng nếu anh còn đang làm thì tôi bỏ qua phòng đó cũng được."]],"qs":[{"n":53,"q":"What problem does the man mention?","qvi":"Người đàn ông nêu vấn đề gì?","opts":["He had to spend extra time on another project.","He does not have the tools he needs.","He must order some special parts for the work.","He had the wrong address information."],"vi":["Phải làm thêm giờ cho dự án khác.","Không có dụng cụ cần thiết.","Phải đặt linh kiện đặc biệt.","Ghi sai địa chỉ."],"ans":"D","xp":"'I wrote down the wrong address' → (D)."},{"n":54,"q":"Why did the woman contact the man?","qvi":"Vì sao người phụ nữ liên hệ người đàn ông?","opts":["A window does not close.","A machine is not turned on.","A water pipe has been damaged.","A door needs to be painted."],"vi":["Cửa sổ không đóng được.","Máy không bật được.","Ống nước bị hỏng.","Cửa cần sơn lại."],"ans":"A","xp":"'the window in our employee lounge is stuck open' → (A)."},{"n":55,"q":"What does the woman plan to do at eleven o'clock?","qvi":"Lúc 11 giờ người phụ nữ định làm gì?","opts":["Pick up a package","Give a building tour","Make a payment","Conduct staff interviews"],"vi":["Nhận bưu kiện","Dẫn tham quan tòa nhà","Thanh toán","Phỏng vấn nhân viên"],"ans":"B","xp":"'give a tour of our building to our new employees at eleven o'clock' → (B)."}],"a":"XC-T10-53-55.mp3"},{"ns":[56,58],"script":[["W1","Ms. Jones, there's a man on the phone with an inquiry about a new project for his pharmacy. Press eight to pick up the call.","Chị Jones, có một người đàn ông gọi điện hỏi về dự án mới cho hiệu thuốc của ông ấy. Chị bấm số 8 để nghe máy."],["W2","Hello, this is Elaine Jones from Freshway Reproductions. How may I help you?","Xin chào, tôi là Elaine Jones ở Freshway Reproductions. Tôi giúp gì được ạ?"],["M","Good morning. I'm a pharmacist at a business downtown, and I'd like to order some banners to promote a new service.","Chào buổi sáng. Tôi là dược sĩ ở một hiệu thuốc trung tâm thành phố, tôi muốn đặt in vài băng rôn để quảng bá dịch vụ mới."],["W2","We can definitely print those, and the completed project would be back to you within two business days.","Chúng tôi chắc chắn in được, và sản phẩm hoàn thiện sẽ được gửi lại ông trong hai ngày làm việc."],["M","Great. How much do you charge?","Tuyệt. Giá bao nhiêu?"],["W2","It depends on the size and the number of colors in your design. If you give me that information now, I can e-mail you a quote for the price by two o'clock.","Còn tùy kích thước và số màu trong thiết kế. Nếu ông cho tôi thông tin đó bây giờ, tôi có thể e-mail báo giá trước 2 giờ."]],"qs":[{"n":56,"q":"Where does the man work?","qvi":"Người đàn ông làm việc ở đâu?","opts":["At a pharmacy","At a moving service","At a television studio","At a training institute"],"vi":["Ở hiệu thuốc","Ở dịch vụ chuyển nhà","Ở trường quay truyền hình","Ở viện đào tạo"],"ans":"A","xp":"'I'm a pharmacist at a business downtown' → (A)."},{"n":57,"q":"What does the man want the women's business to do?","qvi":"Người đàn ông muốn công ty của hai người phụ nữ làm gì?","opts":["Renovate a room","Run a newspaper advertisement","Repair some equipment","Print some banners"],"vi":["Cải tạo phòng","Đăng quảng cáo trên báo","Sửa thiết bị","In băng rôn"],"ans":"D","xp":"'I'd like to order some banners' – 'We can definitely print those' → (D)."},{"n":58,"q":"What will Ms. Jones do later today?","qvi":"Lát nữa hôm nay chị Jones sẽ làm gì?","opts":["Adjust work schedules","Design a logo","Provide pricing information","Visit the man's business"],"vi":["Điều chỉnh lịch làm việc","Thiết kế logo","Cung cấp thông tin giá","Đến chỗ người đàn ông"],"ans":"C","xp":"'I can e-mail you a quote for the price by two o'clock' → (C)."}],"a":"XC-T10-56-58.mp3"},{"ns":[59,61],"script":[["W","Stephen, one of our law firm's clients gave us some baseball tickets as a thank-you. Some of the staff members are going to the game at 3 P.M. on Saturday. Would you like to come along?","Stephen, một khách hàng của văn phòng luật mình tặng vé xem bóng chày để cảm ơn. Vài nhân viên sẽ đi xem trận lúc 3 giờ chiều thứ Bảy. Anh đi cùng không?"],["M","I'm coming to the office on Saturday.","Thứ Bảy tôi phải lên văn phòng."],["W","Oh, that's too bad. Do you have an urgent project to finish up?","Ồ, tiếc quá. Anh có dự án gấp phải làm xong à?"],["M","Yes, a licensing contract for a major client. One of my team members was away on leave this week, so I'm behind schedule.","Đúng vậy, một hợp đồng cấp phép cho khách hàng lớn. Tuần này một người trong nhóm tôi nghỉ phép nên tôi bị chậm tiến độ."]],"qs":[{"n":59,"q":"Where do the speakers work?","qvi":"Họ làm việc ở đâu?","opts":["At an ad agency","At a sports stadium","At a theater","At a law office"],"vi":["Ở công ty quảng cáo","Ở sân vận động","Ở nhà hát","Ở văn phòng luật"],"ans":"D","xp":"'one of our law firm's clients' → (D). (B) liên tưởng vé bóng chày."},{"n":60,"q":"Why does the man say, \"I'm coming to the office on Saturday\"?","qvi":"Vì sao người đàn ông nói \"Thứ Bảy tôi phải lên văn phòng\"?","opts":["To ask for an extra payment","To reschedule a meeting","To decline an invitation","To reassure the woman"],"vi":["Để đòi thêm tiền","Để đổi lịch họp","Để từ chối lời mời","Để trấn an người phụ nữ"],"ans":"C","xp":"Được mời đi xem bóng chày thứ Bảy, ông nói thứ Bảy phải đi làm → từ chối; cô đáp 'that's too bad' → (C)."},{"n":61,"q":"What caused the man to be busier than usual?","qvi":"Điều gì khiến người đàn ông bận hơn thường lệ?","opts":["An absent employee","An urgent order","Some malfunctioning equipment","Some client requests"],"vi":["Một nhân viên vắng mặt","Đơn hàng gấp","Thiết bị hỏng","Yêu cầu của khách"],"ans":"A","xp":"'One of my team members was away on leave this week, so I'm behind schedule' → (A)."}],"a":"XC-T10-59-61.mp3"},{"ns":[62,64],"script":[["W","Hi, Brett. It's Megan. I'm afraid I'm going to get back from my meeting later than expected. I just missed the 1:25 train, and the next one isn't for another hour.","Chào Brett, Megan đây. E là tôi sẽ về muộn hơn dự kiến sau cuộc họp. Tôi vừa lỡ chuyến tàu 1 giờ 25, chuyến sau phải một tiếng nữa."],["M","That could be a problem. At three o'clock, you're supposed to show the new lab technicians how to use the scanning probe microscope.","Vậy có thể gặp rắc rối. Lúc 3 giờ chị phải hướng dẫn các kỹ thuật viên phòng thí nghiệm mới cách dùng kính hiển vi đầu dò quét."],["W","Oh, I had forgotten about that! Could they cover something else first?","Ôi, tôi quên mất! Họ học nội dung khác trước được không?"],["M","Hmm... Simon could probably give his talk first. That would give you enough time to get back. I could ask him now.","Hừm... Có lẽ Simon có thể nói phần của anh ấy trước. Như vậy chị sẽ kịp về. Tôi có thể hỏi anh ấy ngay."],["W","Thanks! Let me know what he says.","Cảm ơn! Báo tôi anh ấy nói sao nhé."]],"qs":[{"n":62,"q":"Look at the graphic. Where is the woman trying to go?","qvi":"Nhìn hình. Người phụ nữ đang muốn đi đâu?","opts":["Dove Valley","Lakewood","Stonegate","Thornton"],"vi":["Dove Valley","Lakewood","Stonegate","Thornton"],"ans":"B","xp":"'I just missed the 1:25 train'; bảng: chuyến 1:25 đi Lakewood → (B)."},{"n":63,"q":"What does the man remind the woman about?","qvi":"Người đàn ông nhắc người phụ nữ về điều gì?","opts":["Scheduled laboratory inspections","Some interviews with job candidates","Her deadline for a report","Her demonstration of some equipment"],"vi":["Lịch kiểm tra phòng thí nghiệm","Phỏng vấn ứng viên","Hạn nộp báo cáo","Buổi hướng dẫn dùng thiết bị của cô"],"ans":"D","xp":"'At three o'clock, you're supposed to show the new lab technicians how to use the scanning probe microscope' → (D)."},{"n":64,"q":"What does the man offer to do?","qvi":"Người đàn ông đề nghị làm gì?","opts":["Speak to a coworker","Print out training materials","E-mail some information","Work extra hours"],"vi":["Nói chuyện với đồng nghiệp","In tài liệu đào tạo","E-mail thông tin","Làm thêm giờ"],"ans":"A","xp":"'Simon could probably give his talk first... I could ask him now' → hỏi đồng nghiệp → (A)."}],"a":"XC-T10-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["W","Good morning. I would like to have this item cleaned and polished. The charge would be seven pounds, right?","Chào buổi sáng. Tôi muốn làm sạch và đánh bóng món đồ này. Giá là 7 bảng, phải không?"],["M","Yes, that's right. Is this item insured?","Vâng, đúng rồi. Món đồ này có bảo hiểm chưa?"],["W","Not yet. I was thinking about insuring it, but I don't know its exact value since it was a gift.","Chưa. Tôi định mua bảo hiểm, nhưng không biết giá trị chính xác vì nó là quà tặng."],["M","Well, you're in luck. We're running a special promotion this week. You can get your jewelry professionally appraised for just forty pounds.","Chị may đấy. Tuần này chúng tôi có khuyến mãi đặc biệt. Chị có thể nhờ chuyên gia định giá trang sức chỉ với 40 bảng."],["W","Oh, that's a good deal. I'll get that service as well. When can I pick up my item?","Ồ, hời quá. Tôi dùng thêm dịch vụ đó. Khi nào tôi lấy đồ được?"],["M","You can come back Thursday afternoon. But remember that you'll need to show your receipt. Otherwise, we won't be able to release the item.","Chiều thứ Năm chị quay lại nhé. Nhưng nhớ mang theo biên lai. Nếu không chúng tôi không thể trả đồ."]],"qs":[{"n":65,"q":"Look at the graphic. What item did the woman bring to the shop?","qvi":"Nhìn hình. Người phụ nữ mang món gì đến cửa hàng?","opts":["A ring","A necklace","A pair of earrings","A bracelet"],"vi":["Nhẫn","Dây chuyền","Đôi bông tai","Vòng tay"],"ans":"D","xp":"'The charge would be seven pounds, right?'; bảng giá: Bracelet £7.00 → (D)."},{"n":66,"q":"Why will the woman pay an extra fee?","qvi":"Vì sao người phụ nữ sẽ trả thêm phí?","opts":["To have an item delivered","To find out the value of an item","To have a service completed quickly","To make some repairs to an item"],"vi":["Để giao đồ","Để biết giá trị món đồ","Để làm dịch vụ nhanh","Để sửa món đồ"],"ans":"B","xp":"'I don't know its exact value' – 'get your jewelry professionally appraised for just forty pounds' – 'I'll get that service as well' → định giá → (B)."},{"n":67,"q":"What is the woman reminded to do?","qvi":"Người phụ nữ được nhắc làm gì?","opts":["Review an insurance policy","Bring a receipt","Call the business on Thursday","Present a coupon"],"vi":["Xem lại hợp đồng bảo hiểm","Mang biên lai","Gọi cửa hàng vào thứ Năm","Xuất trình phiếu giảm giá"],"ans":"B","xp":"'remember that you'll need to show your receipt' → (B)."}],"a":"XC-T10-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["W","Matthew, since we're updating the look of our user guides for equipment, I've checked out some design companies.","Matthew, vì mình đang làm mới hình thức sách hướng dẫn sử dụng thiết bị, tôi đã tìm hiểu vài công ty thiết kế."],["M","Great. We want the guides to be helpful as well as visually appealing. What did you find?","Tốt lắm. Mình muốn sách hướng dẫn vừa hữu ích vừa đẹp mắt. Chị tìm được gì?"],["W","Well, there's a local company called Volex Designs that has reasonable prices. Here's an outline of their process.","Có một công ty địa phương tên Volex Designs giá hợp lý. Đây là sơ đồ quy trình làm việc của họ."],["M","Hmm... well, I don't want to commit to anything until we see their work.","Hừm... tôi không muốn cam kết gì cho đến khi thấy sản phẩm của họ."],["W","Don't worry. We don't have to sign the contract until they show us their first samples.","Đừng lo. Mình chưa phải ký hợp đồng cho đến khi họ cho xem mẫu đầu tiên."],["M","In that case, go ahead and set it up. I'd like this work to be done before I take a summer vacation next month.","Vậy thì cứ tiến hành đi. Tôi muốn việc này xong trước khi tôi đi nghỉ hè tháng sau."]],"qs":[{"n":68,"q":"What are the speakers mainly discussing?","qvi":"Họ chủ yếu bàn về điều gì?","opts":["Advertising campaigns","Company restructuring","Product reviews","Instruction manuals"],"vi":["Chiến dịch quảng cáo","Tái cơ cấu công ty","Đánh giá sản phẩm","Sách hướng dẫn sử dụng"],"ans":"D","xp":"'updating the look of our user guides for equipment' → user guides = instruction manuals → (D)."},{"n":69,"q":"Look at the graphic. When should a contract be signed?","qvi":"Nhìn hình. Khi nào nên ký hợp đồng?","opts":["After Step 1","After Step 2","After Step 3","After Step 4"],"vi":["Sau bước 1","Sau bước 2","Sau bước 3","Sau bước 4"],"ans":"B","xp":"'We don't have to sign the contract until they show us their first samples'; sơ đồ: Step 2 – Volex prepares sample work → ký sau bước 2 → (B)."},{"n":70,"q":"What does the man plan to do next month?","qvi":"Tháng sau người đàn ông định làm gì?","opts":["Announce a staff promotion","Go on a vacation","Purchase new computers","Present an award"],"vi":["Thông báo thăng chức","Đi nghỉ","Mua máy tính mới","Trao giải"],"ans":"B","xp":"'before I take a summer vacation next month' → (B)."}],"a":"XC-T10-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["","Excuse me, everyone. I need a quick word with the kitchen staff. One of our dishwashers is not working properly, so we need to reassign some daily duties of kitchen assistants to cover this work. Brian called the manufacturer, and unfortunately, they said someone can visit us to take a look at it next week. Sorry for the inconvenience. And, today, we will introduce our new cheesecake dessert platter. We have advertised it in a local magazine, so I expect there will be a rush for it. I hope you are well prepared for this change.","Xin lỗi mọi người, tôi cần nói nhanh với nhân viên bếp. Một máy rửa bát của chúng ta đang trục trặc, nên cần phân lại một số việc hằng ngày của phụ bếp để làm thay phần việc này. Brian đã gọi nhà sản xuất, nhưng tiếc là họ nói tuần sau mới có người đến xem được. Xin lỗi vì sự bất tiện. Ngoài ra, hôm nay chúng ta sẽ ra mắt đĩa tráng miệng bánh phô mai mới. Chúng ta đã quảng cáo trên tạp chí địa phương nên tôi đoán sẽ có nhiều khách gọi món này. Mong mọi người chuẩn bị tốt cho thay đổi này."]],"qs":[{"n":71,"q":"Who is the speaker addressing?","qvi":"Người nói đang nói với ai?","opts":["Customers","Kitchen staff members","Servers","Managers"],"vi":["Khách hàng","Nhân viên bếp","Nhân viên phục vụ bàn","Quản lý"],"ans":"B","xp":"'I need a quick word with the kitchen staff' → (B)."},{"n":72,"q":"What problem does the speaker mention?","qvi":"Người nói nêu vấn đề gì?","opts":["An item is out of stock.","A department is understaffed.","An incorrect bill was sent.","A device is malfunctioning."],"vi":["Một món hết hàng.","Một bộ phận thiếu người.","Gửi nhầm hóa đơn.","Một thiết bị bị trục trặc."],"ans":"D","xp":"'One of our dishwashers is not working properly' → (D)."},{"n":73,"q":"What will take place today?","qvi":"Hôm nay sẽ có gì?","opts":["An additional shipment will arrive.","A job opening will be posted.","A television advertisement will begin.","A new dish will be introduced."],"vi":["Thêm một lô hàng về.","Đăng tin tuyển dụng.","Bắt đầu quảng cáo trên TV.","Ra mắt món ăn mới."],"ans":"D","xp":"'today, we will introduce our new cheesecake dessert platter' → (D). (C) quảng cáo trên tạp chí, không phải TV."}],"a":"XC-T10-71-73.mp3"},{"ns":[74,76],"script":[["","Thank you all for participating in this workshop on the best methods for negotiating business deals. I hope you found it useful. After you leave, it's a good idea to look over the information sheets I distributed again. This will help you to solidify the details in your mind. And remember, our business institute offers a variety of workshops on other essential job skills. If you would like to sign up for any of them, Sandra has the paperwork. She's at the table by the rear entrance.","Cảm ơn mọi người đã tham gia hội thảo về những cách đàm phán thương vụ hiệu quả nhất. Mong là mọi người thấy hữu ích. Sau khi về, mọi người nên đọc lại tờ thông tin tôi đã phát. Điều này giúp ghi nhớ chắc các chi tiết. Và nhớ rằng viện kinh doanh của chúng tôi có nhiều hội thảo về các kỹ năng làm việc thiết yếu khác. Nếu muốn đăng ký hội thảo nào, Sandra có giấy tờ đăng ký. Cô ấy ngồi ở bàn cạnh lối ra phía sau."]],"qs":[{"n":74,"q":"What did the listeners learn about in the workshop?","qvi":"Người nghe đã học gì trong hội thảo?","opts":["Public speaking techniques","Helpful hiring tips","Time-management skills","Negotiation strategies"],"vi":["Kỹ năng nói trước công chúng","Mẹo tuyển dụng","Kỹ năng quản lý thời gian","Chiến lược đàm phán"],"ans":"D","xp":"'this workshop on the best methods for negotiating business deals' → (D)."},{"n":75,"q":"What does the speaker encourage the listeners to do?","qvi":"Người nói khuyến khích người nghe làm gì?","opts":["Review some handouts","Join a mailing list","Role-play with each other","Arrive early next time"],"vi":["Xem lại tài liệu đã phát","Đăng ký nhận thư","Đóng vai với nhau","Lần sau đến sớm"],"ans":"A","xp":"'it's a good idea to look over the information sheets I distributed again' → (A)."},{"n":76,"q":"Why does the speaker say, \"Sandra has the paperwork\"?","qvi":"Vì sao người nói nói \"Sandra có giấy tờ\"?","opts":["To point out an error","To explain an application process","To apologize for some confusion","To request more time for a task"],"vi":["Để chỉ ra lỗi","Để giải thích cách đăng ký","Để xin lỗi vì nhầm lẫn","Để xin thêm thời gian"],"ans":"B","xp":"'If you would like to sign up for any of them, Sandra has the paperwork' → hướng dẫn cách đăng ký → (B)."}],"a":"XC-T10-74-76.mp3"},{"ns":[77,79],"script":[["","Hi, this is Joyce calling from Hollis, Inc. I'd like to follow up on the interior design plans we made for your kitchen renovation. I sent you a contract regarding the work last week. I'm still waiting for you to sign it and return it to me. The mailing address is on the business card I gave you. Or, if you don't have that anymore, you can visit our Web site to find the address there. I hope to hear from you soon.","Xin chào, tôi là Joyce gọi từ công ty Hollis. Tôi muốn hỏi tiếp về bản thiết kế nội thất chúng tôi làm cho việc sửa sang nhà bếp của anh. Tuần trước tôi đã gửi anh hợp đồng về công việc này. Tôi vẫn đang đợi anh ký và gửi lại cho tôi. Địa chỉ gửi thư có trên danh thiếp tôi đã đưa anh. Hoặc nếu anh không còn giữ danh thiếp, anh có thể vào trang web của chúng tôi để tìm địa chỉ. Mong sớm nhận được tin anh."]],"qs":[{"n":77,"q":"What kind of business does the speaker most likely work for?","qvi":"Người nói nhiều khả năng làm cho loại công ty nào?","opts":["A printing company","An interior design firm","A car rental agency","A furniture store"],"vi":["Công ty in ấn","Công ty thiết kế nội thất","Công ty cho thuê xe","Cửa hàng nội thất"],"ans":"B","xp":"'the interior design plans we made for your kitchen renovation' → công ty thiết kế nội thất → (B)."},{"n":78,"q":"What is the speaker waiting to receive?","qvi":"Người nói đang đợi nhận gì?","opts":["A set of photographs","A final invoice","An approved budget","A signed contract"],"vi":["Bộ ảnh","Hóa đơn cuối","Ngân sách đã duyệt","Hợp đồng đã ký"],"ans":"D","xp":"'I'm still waiting for you to sign it and return it to me' (hợp đồng) → (D)."},{"n":79,"q":"Why is the listener directed to visit a Web site?","qvi":"Vì sao người nghe được hướng dẫn vào trang web?","opts":["To complete a questionnaire","To see examples of past work","To sign up for a program","To get a mailing address"],"vi":["Để điền phiếu khảo sát","Để xem các công trình trước","Để đăng ký chương trình","Để lấy địa chỉ gửi thư"],"ans":"D","xp":"'you can visit our Web site to find the address there' → (D)."}],"a":"XC-T10-77-79.mp3"},{"ns":[80,82],"script":[["","I'm just calling this short meeting to go over a few things before your shift begins. For starters, we received an extra-large shipment of strawberries from a local distributor, so we'll put those on display near the shopping carts so that customers can see them. We hope to sell a lot of them this way. Also, we used to accept coupons up to one month after expiration, but we are no longer following this practice. So, please remember to accept only valid coupons. I also wanted to discuss the break schedule, but a customer is already waiting for us. We'll talk about it later this evening.","Tôi mở cuộc họp ngắn này để nói vài việc trước khi ca làm của mọi người bắt đầu. Trước hết, chúng ta nhận được một lô dâu tây rất lớn từ nhà phân phối địa phương, nên sẽ bày chúng gần chỗ xe đẩy mua hàng để khách nhìn thấy. Hy vọng làm vậy sẽ bán được nhiều. Ngoài ra, trước đây chúng ta nhận phiếu giảm giá đến một tháng sau khi hết hạn, nhưng giờ không làm vậy nữa. Vì vậy nhớ chỉ nhận phiếu còn hạn. Tôi cũng muốn bàn về lịch nghỉ giải lao, nhưng đã có khách đang đợi rồi. Tối nay chúng ta sẽ nói tiếp."]],"qs":[{"n":80,"q":"Who most likely is the speaker?","qvi":"Người nói nhiều khả năng là ai?","opts":["A supermarket manager","An equipment vendor","A restaurant supervisor","A cooking instructor"],"vi":["Quản lý siêu thị","Người bán thiết bị","Giám sát nhà hàng","Giáo viên dạy nấu ăn"],"ans":"A","xp":"Nói với nhân viên trước ca làm về bày dâu tây gần xe đẩy mua hàng, phiếu giảm giá → quản lý siêu thị → (A)."},{"n":81,"q":"What are the listeners reminded to do?","qvi":"Người nghe được nhắc làm gì?","opts":["Keep private areas locked","Take personal items with them","Follow a new policy","Read a user manual"],"vi":["Khóa khu vực riêng","Mang theo đồ cá nhân","Làm theo quy định mới","Đọc sách hướng dẫn"],"ans":"C","xp":"'we are no longer following this practice. So, please remember to accept only valid coupons' → (C)."},{"n":82,"q":"What does the speaker most likely mean when he says, \"a customer is already waiting for us\"?","qvi":"Người nói có ý gì khi nói \"đã có khách đang đợi rồi\"?","opts":["An assignment has changed.","A meeting will not continue.","High sales are expected today.","New employees are ready to work."],"vi":["Một nhiệm vụ đã thay đổi.","Cuộc họp sẽ không tiếp tục.","Hôm nay dự kiến bán được nhiều.","Nhân viên mới sẵn sàng làm việc."],"ans":"B","xp":"Muốn bàn lịch nghỉ nhưng khách đã đợi, 'We'll talk about it later this evening' → dừng họp ở đây → (B)."}],"a":"XC-T10-80-82.mp3"},{"ns":[83,85],"script":[["","Hello, this message is for Raul Torres. This is Nicole Hess calling from Venata Bank. My team has received your online inquiry about getting a small business loan for your construction company, and we would like to help make this happen. First of all, you'll need to send me your business plan and statements showing your financial transactions. This will help me to determine the level of funding that may be available to you. If you have any questions, please call me back at 555-3315, extension 20. I'm usually available during all business hours, but tomorrow I'll be conducting interviews for an opening in our department, so please keep that in mind. Thanks!","Xin chào, tin nhắn này gửi anh Raul Torres. Tôi là Nicole Hess gọi từ ngân hàng Venata. Nhóm của tôi đã nhận yêu cầu trực tuyến của anh về khoản vay cho doanh nghiệp nhỏ cho công ty xây dựng của anh, và chúng tôi muốn giúp anh thực hiện. Trước hết, anh cần gửi cho tôi kế hoạch kinh doanh và sao kê giao dịch tài chính. Điều này giúp tôi xác định mức vốn anh có thể được vay. Nếu có câu hỏi, vui lòng gọi lại cho tôi số 555-3315, máy lẻ 20. Tôi thường có mặt suốt giờ làm việc, nhưng ngày mai tôi sẽ phỏng vấn tuyển người cho một vị trí trống trong phòng, xin anh lưu ý. Cảm ơn anh!"]],"qs":[{"n":83,"q":"What is the listener interested in doing?","qvi":"Người nghe muốn làm gì?","opts":["Launching an ad campaign","Applying for a loan","Relocating his business","Selling a property"],"vi":["Mở chiến dịch quảng cáo","Xin vay vốn","Chuyển địa điểm công ty","Bán bất động sản"],"ans":"B","xp":"'your online inquiry about getting a small business loan' → (B)."},{"n":84,"q":"According to the speaker, what should the listener do first?","qvi":"Theo người nói, người nghe nên làm gì trước?","opts":["Open an account","Book an appointment","Submit some paperwork","Confirm a budget"],"vi":["Mở tài khoản","Đặt lịch hẹn","Nộp giấy tờ","Xác nhận ngân sách"],"ans":"C","xp":"'First of all, you'll need to send me your business plan and statements' → (C)."},{"n":85,"q":"Why is the speaker unavailable tomorrow?","qvi":"Vì sao ngày mai người nói không có mặt?","opts":["Her branch has plans to close early.","Her annual vacation will begin.","She is transferring to a new department.","She will interview job candidates."],"vi":["Chi nhánh đóng cửa sớm.","Bắt đầu kỳ nghỉ năm.","Cô chuyển sang phòng mới.","Cô sẽ phỏng vấn ứng viên."],"ans":"D","xp":"'tomorrow I'll be conducting interviews for an opening in our department' → (D)."}],"a":"XC-T10-83-85.mp3"},{"ns":[86,88],"script":[["","You're listening to Radio 3. We hope you're having a great morning. In local news, tonight is the opening of the summer outdoor concert series at Ocala Park. The first show will feature the Redburg Municipal Band. There is no cost to attend this event, but please note that no chairs or seating area will be set up. Therefore, you should think about bringing your own portable seat for your comfort. We'll hear more about the event from its planner, Amy Yang, but first, Ramona Diaz is here to give you the latest on the traffic situation. Over to you, Ramona.","Bạn đang nghe Radio 3. Chúc bạn buổi sáng tốt lành. Tin địa phương: tối nay khai mạc chuỗi hòa nhạc ngoài trời mùa hè ở công viên Ocala. Buổi đầu tiên có ban nhạc thành phố Redburg biểu diễn. Sự kiện miễn phí, nhưng xin lưu ý sẽ không có ghế hay khu ngồi. Vì vậy, bạn nên mang theo ghế xếp để ngồi cho thoải mái. Chúng ta sẽ nghe thêm về sự kiện từ người tổ chức, chị Amy Yang, nhưng trước tiên, Ramona Diaz sẽ cập nhật tình hình giao thông mới nhất. Mời Ramona."]],"qs":[{"n":86,"q":"What kind of event is scheduled for tonight?","qvi":"Tối nay có sự kiện gì?","opts":["A community picnic","A musical performance","An exhibition opening","A political debate"],"vi":["Dã ngoại cộng đồng","Buổi biểu diễn âm nhạc","Khai mạc triển lãm","Tranh luận chính trị"],"ans":"B","xp":"'the opening of the summer outdoor concert series' → (B)."},{"n":87,"q":"What does the speaker recommend that attendees do?","qvi":"Người nói khuyên người tham dự làm gì?","opts":["Bring their own seat","Keep listening for cancellations","Read some reviews online","Buy tickets in advance"],"vi":["Mang ghế riêng","Theo dõi tin hủy","Đọc đánh giá trên mạng","Mua vé trước"],"ans":"A","xp":"'you should think about bringing your own portable seat' → (A). (D) sự kiện miễn phí."},{"n":88,"q":"What does the speaker say that listeners will hear next?","qvi":"Người nói cho biết tiếp theo người nghe sẽ nghe gì?","opts":["A traffic update","An interview","A weather report","An advertisement"],"vi":["Tin giao thông","Một cuộc phỏng vấn","Dự báo thời tiết","Quảng cáo"],"ans":"A","xp":"'but first, Ramona Diaz is here to give you the latest on the traffic situation' → (A). (B) phần nói chuyện với Amy Yang là sau đó."}],"a":"XC-T10-86-88.mp3"},{"ns":[89,91],"script":[["","It's wonderful to see so many people here to celebrate Ms. Fisher's retirement with her. I have conflicting feelings about this, as I wish her all the best, but I'll be disappointed not to work with her anymore. Ms. Fisher has been a key member of the company for thirty years. She always put the company first. Ms. Fisher says that she is looking forward to having more free time. In fact, next month, she has plans to take a much-needed vacation, visiting a number of countries in Europe and Asia.","Thật tuyệt khi thấy nhiều người đến đây mừng bà Fisher nghỉ hưu. Tôi có cảm xúc lẫn lộn: tôi chúc bà mọi điều tốt đẹp, nhưng cũng buồn vì không được làm việc với bà nữa. Bà Fisher là thành viên chủ chốt của công ty suốt 30 năm. Bà luôn đặt công ty lên hàng đầu. Bà Fisher nói bà mong có thêm thời gian rảnh. Thật vậy, tháng sau bà định đi một kỳ nghỉ rất xứng đáng, thăm nhiều nước ở châu Âu và châu Á."]],"qs":[{"n":89,"q":"Where is the speech being given?","qvi":"Bài phát biểu diễn ra ở đâu?","opts":["At a retirement party","At an awards banquet","At an orientation session","At a group interview"],"vi":["Ở tiệc nghỉ hưu","Ở tiệc trao giải","Ở buổi định hướng","Ở buổi phỏng vấn nhóm"],"ans":"A","xp":"'so many people here to celebrate Ms. Fisher's retirement' → (A)."},{"n":90,"q":"Why does the speaker say, \"She always put the company first\"?","qvi":"Vì sao người nói nói \"Bà luôn đặt công ty lên hàng đầu\"?","opts":["To outline job responsibilities","To recommend a colleague","To explain a decision","To show appreciation"],"vi":["Để nêu trách nhiệm công việc","Để giới thiệu đồng nghiệp","Để giải thích một quyết định","Để bày tỏ sự trân trọng"],"ans":"D","xp":"Trong bài phát biểu chia tay, khen bà là thành viên chủ chốt 30 năm, luôn vì công ty → bày tỏ trân trọng → (D)."},{"n":91,"q":"What is Ms. Fisher going to do next month?","qvi":"Tháng sau bà Fisher sẽ làm gì?","opts":["Publish an article","Open a new business","Travel internationally","Transfer to a new branch"],"vi":["Đăng bài báo","Mở công ty mới","Đi du lịch nước ngoài","Chuyển chi nhánh"],"ans":"C","xp":"'next month... visiting a number of countries in Europe and Asia' → (C)."}],"a":"XC-T10-89-91.mp3"},{"ns":[92,94],"script":[["","Good afternoon. My name is Seth, and I'll be your guide on this tour of the museum's latest photography exhibit. We are proud to be featuring the work of Alma Heinrich, who is known worldwide for her talent and creativity. She uses both color and black-and-white images to capture her subjects. As you'll see throughout the tour, Ms. Heinrich focuses on animals in danger of extinction all over the world. As this is the first day of the exhibit, we're offering a complimentary poster of Ms. Heinrich's work to all tour participants. Be sure to show your ticket at the gift shop counter at the end of the tour to claim yours.","Chào buổi chiều. Tôi là Seth, hướng dẫn viên cho chuyến tham quan triển lãm ảnh mới nhất của bảo tàng. Chúng tôi tự hào giới thiệu tác phẩm của Alma Heinrich, người nổi tiếng thế giới nhờ tài năng và óc sáng tạo. Bà dùng cả ảnh màu và ảnh đen trắng để ghi lại đối tượng. Như mọi người sẽ thấy trong chuyến đi, bà Heinrich tập trung vào các loài động vật có nguy cơ tuyệt chủng trên khắp thế giới. Vì đây là ngày đầu triển lãm, chúng tôi tặng một tấm áp phích tác phẩm của bà Heinrich cho tất cả người tham gia tour. Cuối chuyến đi, nhớ xuất trình vé ở quầy cửa hàng quà tặng để nhận nhé."]],"qs":[{"n":92,"q":"Who most likely is Alma Heinrich?","qvi":"Alma Heinrich nhiều khả năng là ai?","opts":["A poet","A photographer","A tour guide","A journalist"],"vi":["Nhà thơ","Nhiếp ảnh gia","Hướng dẫn viên","Nhà báo"],"ans":"B","xp":"'the museum's latest photography exhibit... the work of Alma Heinrich' → (B). (C) hướng dẫn viên là Seth."},{"n":93,"q":"According to the speaker, what does Ms. Heinrich like to focus on?","qvi":"Theo người nói, bà Heinrich thích tập trung vào điều gì?","opts":["Rural lives","Scenic roads","Old cars","Endangered animals"],"vi":["Đời sống nông thôn","Những con đường đẹp","Xe cổ","Động vật có nguy cơ tuyệt chủng"],"ans":"D","xp":"'focuses on animals in danger of extinction' → (D)."},{"n":94,"q":"What are the listeners eligible to receive?","qvi":"Người nghe được nhận gì?","opts":["A museum map","A gift shop discount","A free poster","A ticket refund"],"vi":["Bản đồ bảo tàng","Giảm giá ở cửa hàng quà tặng","Áp phích miễn phí","Hoàn tiền vé"],"ans":"C","xp":"'a complimentary poster... to all tour participants' → complimentary = free → (C)."}],"a":"XC-T10-92-94.mp3"},{"ns":[95,97],"script":[["","May I have your attention, please? Passengers on Flight 967 to San Francisco should note the following change. Renovation work in Terminal C, which includes building new ticket counters in several areas, was supposed to be finished by today, but unfortunately, it was not. That means that if you have checked in early online, the system might have assigned you the wrong gate. Please note that this flight is departing from Gate F12. If you are traveling with babies, seniors, or anyone with mobility issues, please pick up the nearest service phone to inform us of the situation. We will send an electric cart to transport you and your luggage.","Xin quý khách chú ý. Hành khách chuyến bay 967 đi San Francisco xin lưu ý thay đổi sau. Việc cải tạo nhà ga C, gồm xây quầy vé mới ở nhiều khu, lẽ ra xong trước hôm nay nhưng tiếc là chưa xong. Điều đó có nghĩa nếu quý khách đã làm thủ tục trực tuyến sớm, hệ thống có thể đã xếp nhầm cửa ra máy bay. Xin lưu ý chuyến bay này khởi hành từ cửa F12. Nếu quý khách đi cùng em bé, người cao tuổi hoặc người đi lại khó khăn, vui lòng nhấc điện thoại dịch vụ gần nhất để báo cho chúng tôi. Chúng tôi sẽ gửi xe điện đến chở quý khách và hành lý."]],"qs":[{"n":95,"q":"What problem does the speaker mention?","qvi":"Người nói nêu vấn đề gì?","opts":["A construction project is not completed.","A flight has been overbooked.","Some severe weather has caused a delay.","A staff member did not arrive for work."],"vi":["Công trình xây dựng chưa xong.","Chuyến bay bán quá số vé.","Thời tiết xấu gây trễ.","Một nhân viên không đi làm."],"ans":"A","xp":"'Renovation work in Terminal C... was supposed to be finished by today, but unfortunately, it was not' → (A)."},{"n":96,"q":"Look at the graphic. Which information is incorrect?","qvi":"Nhìn hình. Thông tin nào bị sai?","opts":["1:35 P.M.","2 hrs 25 min","D14","35A"],"vi":["1:35 chiều","2 giờ 25 phút","D14","35A"],"ans":"C","xp":"'this flight is departing from Gate F12'; vé ghi Gate D14 → cửa ra máy bay bị sai → (C)."},{"n":97,"q":"What does the speaker offer for those traveling with seniors?","qvi":"Người nói đề nghị gì cho người đi cùng người cao tuổi?","opts":["Transportation","A seat upgrade","A fast boarding service","Double reward points"],"vi":["Phương tiện đưa đón","Nâng hạng ghế","Lên máy bay nhanh","Gấp đôi điểm thưởng"],"ans":"A","xp":"'We will send an electric cart to transport you and your luggage' → (A)."}],"a":"XC-T10-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["","To begin today's meeting, I'd like to inform you that our company will host a writing workshop on June 25. This is a great way to promote our magazine publications, as well as help aspiring writers. You're welcome to attend as many sessions as you like, since it will be held here at our office. I think the Style Choices session will be of particular interest. Please note that all employees are required to attend the session at ten o'clock, so make sure you leave time for that in your schedule. Now, I'm not exactly sure how many other people have registered for the workshop, but I'll get that information soon.","Để bắt đầu buổi họp hôm nay, tôi xin thông báo công ty sẽ tổ chức hội thảo viết văn vào ngày 25 tháng 6. Đây là cách tuyệt vời để quảng bá các ấn phẩm tạp chí của chúng ta, đồng thời giúp những người muốn trở thành nhà văn. Mọi người có thể dự bao nhiêu phiên cũng được vì hội thảo tổ chức ngay tại văn phòng. Tôi nghĩ phiên Style Choices sẽ đặc biệt thú vị. Xin lưu ý tất cả nhân viên bắt buộc dự phiên lúc 10 giờ, nên nhớ chừa thời gian trong lịch. Hiện tôi chưa biết chính xác có bao nhiêu người khác đã đăng ký hội thảo, nhưng tôi sẽ sớm có thông tin đó."]],"qs":[{"n":98,"q":"Where do the listeners most likely work?","qvi":"Người nghe nhiều khả năng làm ở đâu?","opts":["At an educational institute","At a magazine publisher","At a newspaper office","At a public library"],"vi":["Ở viện giáo dục","Ở nhà xuất bản tạp chí","Ở tòa soạn báo","Ở thư viện công cộng"],"ans":"B","xp":"'promote our magazine publications' → (B)."},{"n":99,"q":"Look at the graphic. Which session will all employees attend?","qvi":"Nhìn hình. Tất cả nhân viên sẽ dự phiên nào?","opts":["Welcome Speech","Using Technology","Research Methods","Style Choices"],"vi":["Phát biểu chào mừng","Sử dụng công nghệ","Phương pháp nghiên cứu","Lựa chọn phong cách"],"ans":"C","xp":"'all employees are required to attend the session at ten o'clock'; lịch: 10:00 A.M. – Research Methods → (C). (D) chỉ là phiên người nói thấy thú vị."},{"n":100,"q":"What information will the speaker obtain soon?","qvi":"Người nói sẽ sớm có thông tin gì?","opts":["A new seminar schedule","A keynote speaker's profile","The number of participants","A list of participating vendors"],"vi":["Lịch hội thảo mới","Hồ sơ diễn giả chính","Số người tham gia","Danh sách nhà cung cấp tham gia"],"ans":"C","xp":"'I'm not exactly sure how many other people have registered... I'll get that information soon' → (C)."}],"a":"XC-T10-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"Ms. Floyd will ------- the information to all of her employees.","opts":["forwarded","forward","forwards","forwarding"],"ans":"B","xp":"Động từ. Sau động từ khiếm khuyết 'will' cần động từ nguyên thể → (B) forward 'chuyển tiếp'. (A) V2/V3, (C) chia ngôi 3, (D) V-ing.\nDịch: Bà Floyd sẽ chuyển thông tin này cho toàn bộ nhân viên của bà."},{"n":102,"q":"------- the recent economic crisis, Richland Manufacturing has increased its workforce by 15 percent.","opts":["About","Instead","Very","Despite"],"ans":"D","xp":"Giới từ. Sau chỗ trống là cụm danh từ 'the recent economic crisis', ý đối lập (khủng hoảng nhưng vẫn tăng nhân sự) → (D) Despite 'mặc dù'. (A) About, (B) Instead (of), (C) Very không hợp.\nDịch: Bất chấp khủng hoảng kinh tế gần đây, Richland Manufacturing đã tăng 15% nhân sự."},{"n":103,"q":"The HR department will throw a party to ------- Ariel Pacheco, the new chief financial officer.","opts":["welcome","replace","transfer","retire"],"ans":"A","xp":"Từ vựng. Tổ chức tiệc để 'chào đón' giám đốc tài chính mới → (A) welcome. (B) replace 'thay thế', (C) transfer 'điều chuyển', (D) retire 'nghỉ hưu' không hợp.\nDịch: Phòng nhân sự sẽ tổ chức tiệc chào đón Ariel Pacheco, giám đốc tài chính mới."},{"n":104,"q":"Switzerland's most ------- chocolatier will soon be expanding into Germany.","opts":["popularity","popularly","popular","popularize"],"ans":"C","xp":"Từ loại. 'most + tính từ + danh từ' (so sánh nhất) → (C) popular. (A) danh từ, (B) trạng từ, (D) động từ.\nDịch: Hãng sô-cô-la nổi tiếng nhất Thụy Sĩ sắp mở rộng sang Đức."},{"n":105,"q":"Norman Technologies' sales ------- in the last quarter even though it introduced a new product.","opts":["fail","falls","fell","fallen"],"ans":"C","xp":"Thì động từ. Có 'in the last quarter' (quý trước) → quá khứ đơn (C) fell 'giảm'. (A) nguyên thể, (B) hiện tại, (D) V3 cần trợ động từ.\nDịch: Doanh số của Norman Technologies giảm trong quý trước dù công ty đã ra mắt sản phẩm mới."},{"n":106,"q":"The ------- of discount chain stores to the Akron Mall can bring in more low-budget shoppers.","opts":["addition","vendor","service","position"],"ans":"A","xp":"Từ vựng. the addition of A to B = việc bổ sung A vào B → (A). (B) vendor 'người bán', (C) service 'dịch vụ', (D) position 'vị trí' không đi với 'to the Akron Mall'.\nDịch: Việc có thêm các chuỗi cửa hàng giảm giá ở trung tâm thương mại Akron có thể thu hút thêm người mua sắm ít tiền."},{"n":107,"q":"Mr. Cohen is conducting a survey to see if more serving staff members should -------.","opts":["have hired","be hiring","hire","be hired"],"ans":"D","xp":"Thể bị động. Nhân viên phục vụ 'được tuyển' và không có tân ngữ phía sau → should be + V3 (D) be hired. (A) have hired, (B) be hiring, (C) hire đều chủ động, cần tân ngữ.\nDịch: Ông Cohen đang khảo sát xem có nên tuyển thêm nhân viên phục vụ không."},{"n":108,"q":"When returning books ------- of library hours, please use the book drop box near the entrance.","opts":["across","outside","until","except"],"ans":"B","xp":"Giới từ. outside of library hours = ngoài giờ mở cửa thư viện → (B). (A) across 'băng qua', (C) until 'cho đến', (D) except 'ngoại trừ' không hợp.\nDịch: Khi trả sách ngoài giờ mở cửa thư viện, vui lòng dùng thùng trả sách gần lối vào."},{"n":109,"q":"------- customers are encouraged to join a membership of Ramsey Sporting for extra rewards points.","opts":["Frequent","Willing","Repeated","Quick"],"ans":"A","xp":"Từ vựng. frequent customers = khách hàng thường xuyên → (A). (B) willing 'sẵn lòng' (cần to V), (C) repeated 'lặp lại' (dùng cho hành động), (D) quick 'nhanh'.\nDịch: Khách hàng thường xuyên được khuyến khích đăng ký hội viên Ramsey Sporting để có thêm điểm thưởng."},{"n":110,"q":"The ideal candidate for this job ------- would have extensive experience in marketing.","opts":["open","opened","opens","opening"],"ans":"D","xp":"Từ vựng/từ loại. job opening = vị trí tuyển dụng (danh từ ghép) → 'this job opening' (D). (A)(B)(C) là động từ, không tạo cụm danh từ với 'job'.\nDịch: Ứng viên lý tưởng cho vị trí đang tuyển này nên có nhiều kinh nghiệm marketing."},{"n":111,"q":"Don't forget to confirm the shipping address ------- filing a new contract.","opts":["from","to","when","until"],"ans":"C","xp":"Liên từ. when + V-ing = khi làm gì → 'khi lập hợp đồng mới' (C). (A) from, (B) to, (D) until không hợp nghĩa.\nDịch: Đừng quên xác nhận địa chỉ giao hàng khi lập hợp đồng mới."},{"n":112,"q":"Ripley Power, Inc. has produced a new solar panel that is ------- more innovative than any other of its kind.","opts":["considerable","considerably","considering","considered"],"ans":"B","xp":"Từ loại. Trước so sánh hơn 'more innovative' cần trạng từ chỉ mức độ → (B) considerably 'đáng kể'. (A) tính từ, (C)(D) V-ing/V3.\nDịch: Ripley Power đã sản xuất tấm pin mặt trời mới sáng tạo hơn hẳn mọi loại cùng dòng."},{"n":113,"q":"The CEO of Neo Producers ------- the press that his company's acquisition of Eastland Company has almost been finalized.","opts":["told","stated","spoke","mentioned"],"ans":"A","xp":"Từ vựng. tell + người + that... → 'told the press that' (A). (B) stated, (D) mentioned cần 'to the press', (C) spoke (to/with) không đi trực tiếp với tân ngữ chỉ người + that.\nDịch: Giám đốc điều hành Neo Producers nói với báo chí rằng việc mua lại Eastland Company gần như đã xong."},{"n":114,"q":"All inquiries regarding the new accounting software will be ------- answered by the manager of the technical support team.","opts":["currently","personally","smoothly","equally"],"ans":"B","xp":"Từ vựng. Câu hỏi sẽ được 'chính' trưởng nhóm hỗ trợ kỹ thuật trả lời → (B) personally 'đích thân'. (A) currently 'hiện tại', (C) smoothly 'trôi chảy', (D) equally 'như nhau'.\nDịch: Mọi thắc mắc về phần mềm kế toán mới sẽ do đích thân trưởng nhóm hỗ trợ kỹ thuật trả lời."},{"n":115,"q":"Upon ------- the regular inspection yesterday, Mr. Maki wrote a report of its results to his supervisor.","opts":["complete","completion","completing","completed"],"ans":"C","xp":"Danh động từ. upon + V-ing = ngay khi; phía sau có tân ngữ 'the regular inspection' → (C) completing. (B) completion là danh từ, cần 'of' trước tân ngữ; (A) động từ, (D) V3.\nDịch: Ngay khi hoàn thành đợt kiểm tra định kỳ hôm qua, ông Maki đã viết báo cáo kết quả cho cấp trên."},{"n":116,"q":"Due to Ms. Reyes' plan to retire in September, Dorsey Industries decided to recruit her ------- from inside the company.","opts":["achievement","replacement","ceremony","organization"],"ans":"B","xp":"Từ vựng. Bà Reyes nghỉ hưu → tuyển 'người thay thế' bà → (B) replacement. (A) achievement 'thành tựu', (C) ceremony 'buổi lễ', (D) organization 'tổ chức'.\nDịch: Vì bà Reyes định nghỉ hưu vào tháng 9, Dorsey Industries quyết định tuyển người thay bà từ nội bộ công ty."},{"n":117,"q":"The high-speed Internet service ------- by Coyote Cable has been received favorably by customers.","opts":["provide","provides","provided","providing"],"ans":"C","xp":"Rút gọn mệnh đề quan hệ. Câu đã có động từ chính 'has been received'; dịch vụ 'được cung cấp bởi' Coyote Cable → V3 (C) provided. (D) V-ing mang nghĩa chủ động, sai vì có 'by'.\nDịch: Dịch vụ Internet tốc độ cao do Coyote Cable cung cấp được khách hàng đón nhận tích cực."},{"n":118,"q":"------- he was accepted for the position in Tokyo, Mr. Kim began preparing to move overseas.","opts":["As soon as","If","Whereas","Besides"],"ans":"A","xp":"Liên từ. 'Ngay khi được nhận vào vị trí ở Tokyo, ông Kim bắt đầu chuẩn bị chuyển ra nước ngoài' → (A) As soon as. (B) If 'nếu' không hợp với việc đã xảy ra, (C) Whereas 'trong khi (đối lập)', (D) Besides là giới từ/trạng từ.\nDịch: Ngay khi được nhận vào vị trí ở Tokyo, ông Kim bắt đầu chuẩn bị chuyển ra nước ngoài."},{"n":119,"q":"Special holiday bonuses will be given to the salespeople ------- sales figures exceeded their annual goals.","opts":["who","which","that","whose"],"ans":"D","xp":"Đại từ quan hệ sở hữu. 'the salespeople ------- sales figures' = những nhân viên mà doanh số của họ... → (D) whose + danh từ. (A)(C) who/that cần động từ theo sau, (B) which dùng cho vật.\nDịch: Thưởng dịp lễ đặc biệt sẽ dành cho những nhân viên bán hàng có doanh số vượt chỉ tiêu năm."},{"n":120,"q":"This handbook describes each of the ------- skills for the professional engineering license.","opts":["competing","essential","dedicated","dependent"],"ans":"B","xp":"Từ vựng. essential skills = các kỹ năng thiết yếu → (B). (A) competing 'cạnh tranh', (C) dedicated 'tận tâm', (D) dependent 'phụ thuộc' không hợp.\nDịch: Cuốn sổ tay này mô tả từng kỹ năng thiết yếu để có chứng chỉ hành nghề kỹ sư."},{"n":121,"q":"TEST1I0 281 OL LSaL BoBo Tech's new tablet ------- highly profitable, so the company decided to continue producing it.","opts":["proved","created","earned","applied"],"ans":"A","xp":"Từ vựng. prove + tính từ = hóa ra, tỏ ra → 'proved highly profitable' (A). (B) created, (C) earned, (D) applied cần tân ngữ, không đi trực tiếp với tính từ.\nDịch: Máy tính bảng mới của BoBo Tech hóa ra mang lại lợi nhuận cao, nên công ty quyết định tiếp tục sản xuất."},{"n":122,"q":"Mr. Gates held training sessions for all of the sales floor associates ------- before installing the new cash registers.","opts":["right","almost","often","more"],"ans":"A","xp":"Trạng từ. right before = ngay trước khi → 'right before installing the new cash registers' (A). (B) almost 'gần như', (C) often 'thường', (D) more 'hơn' không đứng trước 'before' theo nghĩa này.\nDịch: Ông Gates tổ chức buổi đào tạo cho tất cả nhân viên bán hàng ngay trước khi lắp máy tính tiền mới."},{"n":123,"q":"Longwood Seniors' Community is well-known for having a ------- and safe neighborhood.","opts":["relaxation","relax","relaxed","relaxing"],"ans":"D","xp":"Từ loại. Cấu trúc song song 'a ------- and safe neighborhood' → cần tính từ như 'safe'; khu dân cư 'mang lại cảm giác thư thái' → (D) relaxing. (C) relaxed 'cảm thấy thư thái' dùng cho người; (A) danh từ, (B) động từ.\nDịch: Khu dân cư người cao tuổi Longwood nổi tiếng là nơi yên bình và an toàn."},{"n":124,"q":"The engineer put the engine in the rear end of the car ------- make it more evenly balanced.","opts":["in addition to","as a result of","in order to","on behalf of"],"ans":"C","xp":"Cụm từ. Sau chỗ trống là động từ nguyên thể 'make' → (C) in order to 'để'. (A) in addition to, (B) as a result of, (D) on behalf of đều đi với danh từ/V-ing.\nDịch: Kỹ sư đặt động cơ ở đuôi xe để xe cân bằng hơn."},{"n":125,"q":"Chester Hall was ------- designed to accommodate a wide variety of musical performances.","opts":["punctually","intentionally","aggressively","enormously"],"ans":"B","xp":"Từ vựng. 'được cố ý thiết kế để phù hợp nhiều loại biểu diễn' → (B) intentionally 'có chủ đích'. (A) punctually 'đúng giờ', (C) aggressively 'quyết liệt', (D) enormously 'cực kỳ' không hợp với 'designed to'.\nDịch: Hội trường Chester được thiết kế có chủ đích để phù hợp với nhiều loại hình biểu diễn âm nhạc."},{"n":126,"q":"------- for employment at successful companies is strong, so job applicants should write impressive résumés.","opts":["Competitor","Compete","Competitive","Competition"],"ans":"D","xp":"Từ loại. Chỗ trống làm chủ ngữ, đi với 'is strong' → danh từ không đếm được (D) Competition 'sự cạnh tranh'. (A) Competitor là danh từ đếm được chỉ người (không hợp nghĩa, cần mạo từ), (B) động từ, (C) tính từ.\nDịch: Cạnh tranh việc làm ở các công ty thành công rất gay gắt, nên người xin việc cần viết sơ yếu lý lịch ấn tượng."},{"n":127,"q":"Board members gathered at the Middleton branch to decide ------- they should sell the company.","opts":["whose","what","who","whether"],"ans":"D","xp":"Liên từ. decide whether + mệnh đề = quyết định có... hay không → (D). (A) whose cần danh từ, (B) what, (C) who cần thiếu thành phần trong mệnh đề sau, nhưng 'they should sell the company' đã đủ.\nDịch: Các thành viên hội đồng quản trị họp ở chi nhánh Middleton để quyết định có nên bán công ty hay không."},{"n":128,"q":"Rainbow Café is always crowded with tourists thanks to its ------- to the National History Museum.","opts":["navigation","attraction","necessity","proximity"],"ans":"D","xp":"Từ vựng. proximity to = sự gần với → 'thanks to its proximity to the museum' (D). (A) navigation 'định hướng', (B) attraction 'điểm hấp dẫn', (C) necessity 'sự cần thiết' không đi với 'to the museum' theo nghĩa này.\nDịch: Quán Rainbow Café luôn đông khách du lịch nhờ nằm gần Bảo tàng Lịch sử Quốc gia."},{"n":129,"q":"Hirohito Robostars has announced that its new assembly robot will be ------- at the Tokyo Expo this summer.","opts":["decreased","referred","unveiled","urged"],"ans":"C","xp":"Từ vựng. be unveiled = được ra mắt, giới thiệu → (C). (A) decreased 'bị giảm', (B) referred (to) 'được nhắc đến', (D) urged 'được thúc giục' không hợp với robot mới tại triển lãm.\nDịch: Hirohito Robostars thông báo robot lắp ráp mới sẽ ra mắt tại Tokyo Expo hè này."},{"n":130,"q":"Travis Barber, a sales team head, requested that he ------- one-on-one interviews with all new salespeople.","opts":["conducted","conducts","conduct","will conduct"],"ans":"C","xp":"Thức giả định. Sau 'requested that' + chủ ngữ, động từ ở dạng nguyên thể → (C) conduct. (A) quá khứ, (B) chia ngôi 3, (D) tương lai không dùng trong cấu trúc này.\nDịch: Travis Barber, trưởng nhóm kinh doanh, đề nghị được tự mình phỏng vấn riêng tất cả nhân viên bán hàng mới."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following letter.","passage":"<p>Huiling Lee<br>Pasir Panjang Road<br>Singapore 619998</p><p>Dear Ms. Lee,</p><p>I'd like to inform you about a <span class=\"blank\" data-n=\"131\">-------</span> in our quarterly catalog. We have discontinued the CTR-60 external hard drive, so it should not have been included. I have enclosed the updated copy of the catalog. <span class=\"blank\" data-n=\"132\">-------</span></p><p>Your order for the CTR-60 has been canceled. If you place a new order <span class=\"blank\" data-n=\"133\">-------</span> the next two weeks, you will be eligible for free shipping due to our autumn sale, which runs until October 10. <span class=\"blank\" data-n=\"134\">-------</span> that your order is received in time, we recommend placing it via our Web site, www.ophirelectronics.com.</p><p>Sincerely,<br>Ophir Electronics</p>","vi":"Gửi chị Huiling Lee, đường Pasir Panjang, Singapore 619998\n\nKính gửi chị Lee,\n\nChúng tôi xin thông báo về một lỗi in trong danh mục sản phẩm hằng quý. Chúng tôi đã ngừng bán ổ cứng gắn ngoài CTR-60 nên lẽ ra không đưa sản phẩm này vào danh mục. Tôi gửi kèm bản danh mục đã cập nhật. Bản này sẽ cho chị thấy chính xác những sản phẩm hiện còn.\n\nĐơn đặt CTR-60 của chị đã bị hủy. Nếu chị đặt đơn mới trong vòng hai tuần tới, chị sẽ được miễn phí vận chuyển nhờ đợt khuyến mãi mùa thu kéo dài đến 10/10. Để đơn hàng đến kịp, chúng tôi khuyên chị đặt qua trang web www.ophirelectronics.com.\n\nTrân trọng,\nOphir Electronics","qs":[{"n":131,"opts":["misprint","collection","price","promotion"],"ans":"A","xp":"Từ vựng. Sản phẩm đã ngừng bán nhưng vẫn in trong danh mục ('should not have been included') → lỗi in (A) misprint. (B) collection 'bộ sưu tập', (C) price 'giá', (D) promotion 'khuyến mãi'."},{"n":132,"opts":["We have resolved the safety issue found in earlier versions.","These can be downloaded at no cost to the customer.","The hard drive can store more data than ever before.","It will show you exactly what we have available at this time."],"ans":"D","xp":"Điền câu. Câu trước: 'I have enclosed the updated copy of the catalog' → câu sau nói về bản danh mục mới: 'Nó cho chị thấy chính xác sản phẩm hiện có' (D); 'It' = the updated catalog."},{"n":133,"opts":["thanks to","since","instead of","within"],"ans":"D","xp":"Giới từ. within + khoảng thời gian = trong vòng → 'within the next two weeks' (D). (A) thanks to 'nhờ', (B) since + mốc thời gian quá khứ, (C) instead of 'thay vì'."},{"n":134,"opts":["Ensured","To ensure","Ensures","Having ensured"],"ans":"B","xp":"To V chỉ mục đích đầu câu. 'Để đảm bảo đơn hàng đến kịp, chúng tôi khuyên...' → (B) To ensure. (A)(D) mang nghĩa đã xảy ra/bị động, (C) động từ chia không đứng đầu câu như vậy."}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following memo.","passage":"<div class=\"hdr\"><p><b>To:</b> All Romani Consulting staff</p><p><b>From:</b> Philip Shealey</p><p><b>Date:</b> May 4</p><p><b>Re:</b> Yamal Gupte</p></div><p>Hello Everyone,</p><p>Because so many people participated in the first two professional development skills events, we're pleased to bring you this <span class=\"blank\" data-n=\"135\">-------</span> workshop led by Yamal Gupte. We have arranged for him to visit our company on May 22. Mr. Gupte <span class=\"blank\" data-n=\"136\">-------</span> a number of strategies for maximizing social media for product promotion. This is the only workshop that is available to all staff members. <span class=\"blank\" data-n=\"137\">-------</span> Mr. Gupte is a leading motivational speaker, so this is a fantastic opportunity to learn from him. Ms. Yates in the administration office is responsible for <span class=\"blank\" data-n=\"138\">-------</span> a participant list, so please talk to her to sign up.</p><p>Thank you.</p>","vi":"Gửi: Toàn thể nhân viên Romani Consulting | Từ: Philip Shealey | Ngày: 4/5 | V/v: Yamal Gupte\n\nChào mọi người,\n\nVì rất nhiều người đã tham gia hai sự kiện phát triển kỹ năng nghề nghiệp đầu tiên, chúng tôi vui mừng mang đến hội thảo riêng do Yamal Gupte hướng dẫn. Chúng tôi đã sắp xếp để ông đến công ty ngày 22/5. Ông Gupte sẽ giới thiệu nhiều chiến lược tận dụng mạng xã hội để quảng bá sản phẩm. Đây là hội thảo duy nhất dành cho tất cả nhân viên. Các hội thảo khác chỉ dành cho cấp quản lý. Ông Gupte là diễn giả truyền cảm hứng hàng đầu, nên đây là cơ hội tuyệt vời để học hỏi từ ông. Chị Yates ở văn phòng hành chính phụ trách lập danh sách người tham gia, vì vậy hãy gặp chị ấy để đăng ký.\n\nCảm ơn mọi người.","qs":[{"n":135,"opts":["private","weekly","initial","recent"],"ans":"A","xp":"Từ vựng. Diễn giả đến tận công ty ('visit our company') tổ chức riêng cho nhân viên → hội thảo riêng (A) private. (B) weekly 'hằng tuần' sai vì chỉ có một ngày 22/5, (C) initial 'đầu tiên' sai vì đã có hai sự kiện trước, (D) recent 'gần đây' dùng cho việc đã qua."},{"n":136,"opts":["will introduce","introduced","will have introduced","has been introduced"],"ans":"A","xp":"Thì động từ. Hội thảo ngày 22/5 (sau ngày 4/5) → tương lai đơn (A) will introduce. (B) quá khứ, (C) tương lai hoàn thành không hợp, (D) bị động sai (có tân ngữ 'a number of strategies')."},{"n":137,"opts":["For several years, Mr. Gupte operated a small Web site.","Each activity comes with its own handbook.","The others are for management-level employees only.","You probably have at least one social media account."],"ans":"C","xp":"Điền câu. Câu trước: 'This is the only workshop that is available to all staff members' → câu sau giải thích: 'Các hội thảo khác chỉ dành cho cấp quản lý' (C)."},{"n":138,"opts":["who created","creates","having created","the creation of"],"ans":"D","xp":"Từ loại. Sau giới từ 'for' cần danh từ hoặc V-ing → (D) the creation of 'việc lập'. (C) having created mang nghĩa đã lập xong, không hợp với việc đang nhận đăng ký; (A)(B) là mệnh đề/động từ chia."}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> Fang Jin &lt;fangjin@grand-mail.net&gt;</p><p><b>From:</b> Noah Cole &lt;n.cole@hartway101.net&gt;</p><p><b>Date:</b> September 16</p><p><b>Subject:</b> Freelance Project</p></div><p>Dear Mr. Jin,</p><p>I am the editor of a Web site that posts news from the cosmetics industry. We have set a goal of <span class=\"blank\" data-n=\"139\">-------</span> our contents in five different languages by the end of next year. Since performing English to Chinese translation is your <span class=\"blank\" data-n=\"140\">-------</span>, I think you would be perfect for this project. If you're not working in the cosmetics industry, some of our articles may seem <span class=\"blank\" data-n=\"141\">-------</span> boring, but they are useful to many companies around the world. We have hundreds of articles that need to be translated. To see if we can work well together, I'd like to have you translate five articles at first. <span class=\"blank\" data-n=\"142\">-------</span> Please let me know your availability.</p><p>Thank you!<br>Noah Cole</p>","vi":"Người nhận: Fang Jin | Người gửi: Noah Cole | Ngày: 16/9 | Chủ đề: Dự án làm tự do\n\nKính gửi anh Jin,\n\nTôi là biên tập viên của một trang web đăng tin ngành mỹ phẩm. Chúng tôi đặt mục tiêu cung cấp nội dung bằng năm ngôn ngữ trước cuối năm sau. Vì dịch Anh – Trung là chuyên môn của anh, tôi nghĩ anh rất hợp với dự án này. Nếu anh không làm trong ngành mỹ phẩm, một số bài có thể hơi nhàm chán, nhưng chúng hữu ích với nhiều công ty trên thế giới. Chúng tôi có hàng trăm bài cần dịch. Để xem chúng ta có hợp tác tốt không, trước tiên tôi muốn nhờ anh dịch năm bài. Nếu thành công, chúng tôi sẽ ký hợp đồng toàn thời gian với anh. Vui lòng cho tôi biết lịch của anh.\n\nCảm ơn anh!\nNoah Cole","qs":[{"n":139,"opts":["offers","offering","offer","offered"],"ans":"B","xp":"Danh động từ. Sau giới từ 'of' cần V-ing; phía sau có tân ngữ 'our contents' → (B) offering 'cung cấp'."},{"n":140,"opts":["capacity","requirement","specialty","response"],"ans":"C","xp":"Từ vựng. 'Vì dịch Anh – Trung là chuyên môn của anh' → (C) specialty. (A) capacity 'sức chứa/năng lực', (B) requirement 'yêu cầu', (D) response 'phản hồi'."},{"n":141,"opts":["else","rather","soon","still"],"ans":"B","xp":"Trạng từ chỉ mức độ trước tính từ 'boring' → (B) rather 'khá, hơi'. (A) else, (C) soon, (D) still không bổ nghĩa mức độ cho tính từ theo cách này."},{"n":142,"opts":["If possible, the cosmetics should be shipped quickly.","Sadly, we were disappointed with the level of service.","These visitors can learn a lot from the provided information.","If this is successful, we'll give you a full-time contract."],"ans":"D","xp":"Điền câu. Câu trước: 'To see if we can work well together, I'd like to have you translate five articles at first' (thử trước 5 bài) → câu sau: 'Nếu thành công, chúng tôi sẽ ký hợp đồng toàn thời gian' (D)."}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following article.","passage":"<h3>Relief for Commuters on the Horizon</h3><p>January 5—At a meeting held at City Hall yesterday, the Detroit Highway Association (DHA) announced plans to create a toll road to ease traffic congestion in the western part of the city. <span class=\"blank\" data-n=\"143\">-------</span> Commuters who use the current road often complain about the traffic backups, especially during rush hour. <span class=\"blank\" data-n=\"144\">-------</span>, the city is exploring ways to relieve this pressure without putting an unnecessary burden on taxpayers. Work could begin on the new road as early as this summer. A committee has been set up to <span class=\"blank\" data-n=\"145\">-------</span> bids from contractors. A <span class=\"blank\" data-n=\"146\">-------</span> by committee members will be made on April 1.</p>","vi":"Sắp có giải pháp cho người đi làm\n\n5/1 — Tại cuộc họp ở Tòa thị chính hôm qua, Hiệp hội Đường cao tốc Detroit (DHA) công bố kế hoạch xây một con đường thu phí để giảm ùn tắc giao thông ở phía tây thành phố. Con đường này sẽ là lựa chọn thay thế cho tuyến I-94. Người đi làm dùng tuyến đường hiện tại thường phàn nàn về tình trạng tắc đường, nhất là giờ cao điểm. Vì vậy, thành phố đang tìm cách giảm áp lực này mà không tạo gánh nặng không cần thiết cho người đóng thuế. Con đường mới có thể khởi công sớm nhất vào mùa hè này. Một ủy ban đã được lập để nhận hồ sơ dự thầu từ các nhà thầu. Ủy ban sẽ ra quyết định vào ngày 1/4.","qs":[{"n":143,"opts":["The area has seen a decrease in population.","The city welcomes workers from all over the state.","The road would provide an alternative to route I-94.","The DHA is pleased with the final result."],"ans":"C","xp":"Điền câu. Câu trước: kế hoạch xây đường thu phí để giảm ùn tắc; câu sau: 'Commuters who use the current road often complain' → câu giữa nói đường mới thay thế cho tuyến hiện tại: (C) 'Con đường sẽ là lựa chọn thay thế cho tuyến I-94'."},{"n":144,"opts":["In conclusion","As a result","In contrast","For instance"],"ans":"B","xp":"Trạng từ nối. Người đi làm phàn nàn tắc đường → 'Vì vậy', thành phố tìm cách giảm áp lực → (B) As a result. (A) In conclusion 'tóm lại', (C) In contrast 'ngược lại', (D) For instance 'ví dụ'."},{"n":145,"opts":["accept","insist","convince","launch"],"ans":"A","xp":"Từ vựng. accept bids from contractors = nhận hồ sơ dự thầu → (A). (B) insist 'khăng khăng', (C) convince 'thuyết phục', (D) launch 'khởi động' không đi với 'bids from contractors'."},{"n":146,"opts":["decided","decide","decision","decisive"],"ans":"C","xp":"Từ loại. Sau mạo từ 'A' cần danh từ; make a decision = ra quyết định → (C). (A)(B) động từ, (D) tính từ."}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following notice.","passages":["<h3>Tony's Steakhouse</h3><h4>ENJOY AN APPETIZER ON THE HOUSE!</h4><p>After eating at any of Tony's Steakhouse locations, go online to www.tonyssteak.com/survey to win a coupon for a FREE appetizer of your choice with the purchase of any meal!</p><p>If you are placing a takeout order on the phone and want to apply an appetizer coupon to your bill, please be sure to mention it before coming to pick up your order to ensure that your total is accurate.</p>"],"vi":"Nhà hàng Tony's Steakhouse – Thưởng thức món khai vị miễn phí!\n\nSau khi ăn ở bất kỳ chi nhánh nào của Tony's Steakhouse, hãy vào www.tonyssteak.com/survey để nhận phiếu tặng một món khai vị MIỄN PHÍ tùy chọn khi mua bất kỳ suất ăn nào!\n\nNếu bạn gọi điện đặt món mang về và muốn dùng phiếu khai vị, hãy nhớ nói trước khi đến lấy món để hóa đơn được tính đúng.","qs":[{"n":147,"q":"What is indicated about Tony's Steakhouse?","qvi":"Điều gì được cho biết về Tony's Steakhouse?","opts":["It offers reward points to diners.","It has multiple locations.","It has a separate takeout menu.","It takes online reservations."],"ans":"B","xp":"'After eating at any of Tony's Steakhouse locations' → có nhiều chi nhánh → (B)."},{"n":148,"q":"What are takeout customers asked to do to get a complimentary appetizer?","qvi":"Khách mua mang về được yêu cầu làm gì để nhận món khai vị miễn phí?","opts":["Mention a coupon","Call in advance","Become a member","Use a pick-up counter"],"ans":"A","xp":"'If you are placing a takeout order... want to apply an appetizer coupon... please be sure to mention it' → nói về phiếu → (A)."}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following product review.","passages":["<h3>Armor Shell</h3><p>Even though I'm not a professional photographer, I have enjoyed taking pictures of everyday moments with my high-end digital camera, DP-150. I do my best to handle it with care, but getting worn out and scratched is unavoidable in daily use. Sometimes it slips out of my hand and drops on the floor. That is why I tried the Armor Shell casing to protect my camera from cracking or breaking. Even though it has been bumped into walls and objects, there have been no signs of damage since using Armor Shell. I recommend this product to everyone with a digital camera. If you are skeptical, it offers a 100% satisfaction policy. You can always return it for a full refund if you are not happy with it.</p>"],"vi":"Armor Shell\n\nDù không phải nhiếp ảnh gia chuyên nghiệp, tôi rất thích chụp những khoảnh khắc thường ngày bằng máy ảnh kỹ thuật số cao cấp DP-150. Tôi cố gắng dùng máy cẩn thận, nhưng dùng hằng ngày thì khó tránh bị mòn và trầy xước. Đôi khi máy tuột khỏi tay rơi xuống sàn. Vì thế tôi đã thử vỏ bọc Armor Shell để bảo vệ máy khỏi nứt vỡ. Dù đã va vào tường và đồ vật, từ khi dùng Armor Shell máy không có dấu hiệu hư hỏng nào. Tôi giới thiệu sản phẩm này cho mọi người có máy ảnh kỹ thuật số. Nếu bạn còn nghi ngờ, sản phẩm có chính sách đảm bảo hài lòng 100%. Bạn luôn có thể trả lại để được hoàn tiền đầy đủ nếu không hài lòng.","qs":[{"n":149,"q":"What product is reviewed?","qvi":"Sản phẩm nào được đánh giá?","opts":["An earphone set","A digital camera","A battery charger","A camera case"],"ans":"D","xp":"'I tried the Armor Shell casing to protect my camera' → vỏ bọc máy ảnh → (D). (B) máy ảnh là đồ người viết đã có, không phải sản phẩm được đánh giá."},{"n":150,"q":"What is mentioned about the product?","qvi":"Điều gì được nhắc đến về sản phẩm?","opts":["It received favorable reviews from industry experts.","It has a money-back guarantee.","It is lighter than other similar products.","It is heat and water resistant."],"ans":"B","xp":"'You can always return it for a full refund if you are not happy with it' → bảo đảm hoàn tiền → (B)."}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following text message chain.","passages":["<div class=\"msg\"><p><b>Troy Whitlock 10:11 A.M.</b></p><p>The Getz Corporation representatives will be here this afternoon to present ideas for our spring ad campaign.</p></div><div class=\"msg\"><p><b>Lian Zou 10:12 A.M.</b></p><p>That's for our Angus Athletic line, right?</p></div><div class=\"msg\"><p><b>Troy Whitlock 10:14 A.M.</b></p><p>Yes. Some of the product developers will be there. Are you going?</p></div><div class=\"msg\"><p><b>Lian Zou 10:15 A.M.</b></p><p>Probably not. I was disappointed that the meeting is scheduled to take place in Conference Room C. That's too small to include many people.</p></div><div class=\"msg\"><p><b>Troy Whitlock 10:16 A.M.</b></p><p>It's been changed.</p></div><div class=\"msg\"><p><b>Lian Zou 10:19 A.M.</b></p><p>Oh, really? Where is it now?</p></div><div class=\"msg\"><p><b>Troy Whitlock 10:21 A.M.</b></p><p>In the main conference room. The first presenter will be Carol Dodson at 1 P.M.</p></div><div class=\"msg\"><p><b>Lian Zou 10:22 A.M.</b></p><p>Okay. In that case, I'll be there as long as my manager says it's okay.</p></div>"],"vi":"Troy Whitlock (10:11): Chiều nay đại diện công ty Getz sẽ đến trình bày ý tưởng cho chiến dịch quảng cáo mùa xuân của mình.\nLian Zou (10:12): Cho dòng sản phẩm Angus Athletic của mình phải không?\nTroy Whitlock (10:14): Đúng. Vài người phát triển sản phẩm sẽ có mặt. Chị có đi không?\nLian Zou (10:15): Chắc là không. Tôi thất vọng vì cuộc họp xếp ở phòng hội nghị C. Phòng đó quá nhỏ, không chứa được nhiều người.\nTroy Whitlock (10:16): Đã đổi rồi.\nLian Zou (10:19): Ồ, thật à? Giờ ở đâu?\nTroy Whitlock (10:21): Ở phòng hội nghị chính. Người trình bày đầu tiên là Carol Dodson lúc 1 giờ chiều.\nLian Zou (10:22): Được. Vậy tôi sẽ đến, miễn là quản lý của tôi đồng ý.","qs":[{"n":151,"q":"At 10:16 A.M., what does Mr. Whitlock mean when he writes, \"It's been changed\"?","qvi":"Lúc 10:16, ông Whitlock có ý gì khi viết \"Đã đổi rồi\"?","opts":["A new policy was approved.","A meeting will start late.","Attendance is now mandatory.","A problem has been resolved."],"ans":"D","xp":"Cô Zou chê phòng C quá nhỏ; ông nói đã đổi sang phòng hội nghị chính → vấn đề phòng nhỏ đã được giải quyết → (D)."},{"n":152,"q":"Who most likely is Ms. Dodson?","qvi":"Bà Dodson nhiều khả năng là ai?","opts":["A product developer","A Getz Corporation employee","Ms. Zou's manager","An Angus Athletic investor"],"ans":"B","xp":"Đại diện Getz Corporation đến 'to present ideas'; 'The first presenter will be Carol Dodson' → bà là nhân viên Getz → (B)."}]},{"ns":[153,155],"head":"Questions 153-155 refer to the following notice.","passages":["<h3>Upcoming Events</h3><p>Aurora Theater will be featuring a series of performances this summer from July 6 through August 30. Jackie Astor, who just took over as the theater's head manager last month, announced that she wants to do something new this summer. Unlike previous years, this summer will solely feature solo artists. The move was praised by Nancy Short in her article in the May edition of *Monthly Entertainment in Aurora*. Some of the upcoming solo acts include Mario Torres doing stand-up comedy, Jillian Villa playing Mozart on the piano, and Hector Fray performing monologues based on Shakespeare's original works. In Ms. Short's May article, she mentioned, \"It's not every day you get to enjoy an outdoor concert solo by a recipient of a Golden Piano prize.\" Anyone interested can find more details regarding the event on Aurora Theater's Web site, www.auroratheater.com, or by picking up a pamphlet at the box office.</p>"],"vi":"Sự kiện sắp tới\n\nNhà hát Aurora sẽ có chuỗi biểu diễn mùa hè này từ 6/7 đến 30/8. Bà Jackie Astor, người vừa lên làm quản lý trưởng nhà hát tháng trước, cho biết bà muốn làm điều gì đó mới mẻ mùa hè này. Khác các năm trước, mùa hè này chỉ có các nghệ sĩ biểu diễn đơn. Quyết định này được Nancy Short khen ngợi trong bài viết trên tạp chí Monthly Entertainment in Aurora số tháng 5. Một số tiết mục đơn sắp tới gồm Mario Torres diễn hài độc thoại, Jillian Villa chơi nhạc Mozart trên piano, và Hector Fray trình diễn độc thoại dựa trên nguyên tác của Shakespeare. Trong bài tháng 5, bà Short viết: \"Không phải ngày nào bạn cũng được thưởng thức buổi hòa nhạc độc tấu ngoài trời của một người từng đoạt giải Golden Piano.\" Ai quan tâm có thể xem thêm chi tiết trên trang web www.auroratheater.com hoặc lấy tờ giới thiệu ở phòng vé.","qs":[{"n":153,"q":"What is mentioned about the theater?","qvi":"Điều gì được nhắc đến về nhà hát?","opts":["Its stage is too small for large groups.","It is being operated by new management.","It only operates seasonally.","It recently underwent renovations."],"ans":"B","xp":"'Jackie Astor, who just took over as the theater's head manager last month' → quản lý mới → (B)."},{"n":154,"q":"Who most likely is Ms. Short?","qvi":"Bà Short nhiều khả năng là ai?","opts":["A performer","A film critic","A journalist","A director"],"ans":"C","xp":"'Nancy Short in her article in the May edition of Monthly Entertainment in Aurora' → bà viết báo → nhà báo → (C). (B) bà viết về biểu diễn sân khấu, không phải phim."},{"n":155,"q":"Who has won an award?","qvi":"Ai đã từng đoạt giải?","opts":["Hector Fray","Nancy Short","Mario Torres","Jillian Villa"],"ans":"D","xp":"'an outdoor concert solo by a recipient of a Golden Piano prize' → người chơi piano là Jillian Villa → (D)."}]},{"ns":[156,157],"head":"Questions 156-157 refer to the following contract form.","passages":["<h3>Project Adjustment Details</h3><table><tr><td>Contractor:</td><td>Connie McCarthy - McCarthy Roofing &amp; Siding - 444 Bronson Road, Hardenville, MO 65666</td></tr><tr><td>Client:</td><td>Gregory Houston - 4425 Court Street, Olivette, MO 63132</td></tr><tr><td>Begin On:</td><td>7 August</td></tr><tr><td>Finish By:</td><td>16 August</td></tr></table><p>This document specifies the adjustments made to the original contract signed on 28 July.</p><table><tr><td>Additional / Cancelled Work:</td><td>Weatherproof paint will be used on the siding instead of regular paint as per request of Mr. Houston.</td></tr><tr><td>Original Fee (Including Labor &amp; Materials):</td><td>$4,700</td></tr><tr><td>Net Fee Change:</td><td>$400</td></tr><tr><td>Final Agreed Upon Cost:</td><td>$5,100</td></tr><tr><td>Other Notes:</td><td>10% ($510) is due on the start date. The remainder ($4,590) is due upon completion of the specified work.</td></tr></table><p>Contractor: Connie McCarthy / Client: Gregory Houston</p>"],"vi":"Chi tiết điều chỉnh dự án\n\nNhà thầu: Connie McCarthy – McCarthy Roofing & Siding, 444 Bronson Road, Hardenville | Khách hàng: Gregory Houston, 4425 Court Street, Olivette | Bắt đầu: 7/8 | Hoàn thành trước: 16/8\n\nVăn bản này nêu các điều chỉnh so với hợp đồng gốc ký ngày 28/7.\nCông việc thêm/hủy: Dùng sơn chống chịu thời tiết cho tường ốp ngoài thay vì sơn thường theo yêu cầu của ông Houston.\nPhí ban đầu (gồm công và vật liệu): 4.700 đô | Chênh lệch: 400 đô | Chi phí cuối cùng đã thống nhất: 5.100 đô\nGhi chú: Trả 10% (510 đô) vào ngày bắt đầu. Phần còn lại (4.590 đô) trả khi hoàn thành công việc.\nNhà thầu: Connie McCarthy / Khách hàng: Gregory Houston","qs":[{"n":156,"q":"Why was the original contract altered?","qvi":"Vì sao hợp đồng gốc được sửa đổi?","opts":["A different material was selected.","The work date had to be postponed.","Additional work was requested.","The work needed to be finished earlier."],"ans":"A","xp":"'Weatherproof paint will be used on the siding instead of regular paint' → đổi sang loại sơn khác → vật liệu khác → (A). (C) không thêm việc, chỉ đổi sơn."},{"n":157,"q":"How much will Mr. Houston most likely owe McCarthy Roofing & Siding on 16 August?","qvi":"Ngày 16/8 ông Houston nhiều khả năng phải trả McCarthy Roofing & Siding bao nhiêu?","opts":["$510","$4,590","$4,700","$5,100"],"ans":"B","xp":"Ngày 16/8 là hạn hoàn thành; 'The remainder ($4,590) is due upon completion' → (B). (A) 510 đô trả ngày bắt đầu 7/8."}]},{"ns":[158,160],"head":"Questions 158-160 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Lorna Parnell &lt;lornaparnell@exactagencyteam.com&gt;</p><p><b>From:</b> Asif Mustafi &lt;asif.mustafi@miventerprises.net&gt;</p><p><b>Date:</b> August 15</p><p><b>Subject:</b> Photos</p></div><p>Dear Ms. Parnell,</p><p>Thank you for letting me know about the watermark on the photos you downloaded from our collection for your advertising campaign. As you correctly pointed out, your photos should not have our watermark on them because you are a paid subscriber. <span class=\"pos\">[1]</span> It seems the problem stems from the fact that your assistant sent the purchase request from a personal e-mail account rather than from your business account. <span class=\"pos\">[2]</span> As we process thousands of requests for images each day, we use an automated system. The request was flagged as a \"One-Time Request,\" which contains a watermark so the image can't be copied, when it should have been a \"Paid Subscriber Request,\" which is the full version for corporate use. I have updated the request on our system manually. <span class=\"pos\">[3]</span></p><p>In the future, as long as you process requests using the e-mail address registered on the system, you should have no further difficulties. <span class=\"pos\">[4]</span> Once again, please accept my apologies for any inconvenience caused.</p><p>Best regards,<br>Asif Mustafi<br>Customer Service Manager<br>MIV Enterprises</p>"],"vi":"Người nhận: Lorna Parnell | Người gửi: Asif Mustafi | Ngày: 15/8 | Chủ đề: Ảnh\n\nKính gửi chị Parnell,\n\nCảm ơn chị đã báo về dấu bản quyền (watermark) trên những tấm ảnh chị tải từ kho ảnh của chúng tôi cho chiến dịch quảng cáo. Như chị đã chỉ ra đúng, ảnh của chị lẽ ra không có watermark vì chị là người đăng ký trả phí. Có vẻ vấn đề là do trợ lý của chị gửi yêu cầu mua từ tài khoản e-mail cá nhân thay vì tài khoản công ty của chị. Vì mỗi ngày chúng tôi xử lý hàng nghìn yêu cầu ảnh, chúng tôi dùng hệ thống tự động. Yêu cầu bị đánh dấu là \"Yêu cầu một lần\" – loại có watermark để ảnh không bị sao chép – trong khi lẽ ra phải là \"Yêu cầu của người đăng ký trả phí\" – bản đầy đủ dùng cho doanh nghiệp. Tôi đã cập nhật yêu cầu thủ công trên hệ thống. Giờ chị có thể đăng nhập bình thường và tải đúng phiên bản tệp chị cần.\n\nSau này, chỉ cần gửi yêu cầu bằng địa chỉ e-mail đã đăng ký trên hệ thống thì sẽ không gặp khó khăn nữa. Một lần nữa, xin lỗi chị vì mọi bất tiện.\n\nTrân trọng,\nAsif Mustafi – Quản lý dịch vụ khách hàng, MIV Enterprises","qs":[{"n":158,"q":"What type of company most likely is MIV Enterprises?","qvi":"MIV Enterprises nhiều khả năng là loại công ty nào?","opts":["An Internet provider","A photo library","An advertising agency","A graphic design institute"],"ans":"B","xp":"'the photos you downloaded from our collection'; 'we process thousands of requests for images each day' → kho ảnh → (B). (C) công ty quảng cáo là khách hàng (chị Parnell)."},{"n":159,"q":"What is NOT mentioned by Mr. Mustafi?","qvi":"Điều gì KHÔNG được ông Mustafi nhắc đến?","opts":["The volume of requests processed daily","The difference between account types","The system upgrade requirements","The preferred login method"],"ans":"C","xp":"(A) 'thousands of requests... each day'; (B) 'One-Time Request' và 'Paid Subscriber Request'; (D) dùng e-mail đã đăng ký. Không nói yêu cầu nâng cấp hệ thống → (C)."},{"n":160,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? \"You should now be able to log in normally and download the correct version of the files you need.\"","qvi":"Câu sau phù hợp nhất ở vị trí nào? \"Giờ chị có thể đăng nhập bình thường và tải đúng phiên bản tệp chị cần.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"C","xp":"'now' cho thấy vấn đề vừa được xử lý; câu trước vị trí [3]: 'I have updated the request on our system manually' → (C)."}]},{"ns":[161,164],"head":"Questions 161-164 refer to the following notice.","passages":["<h3>Rational Running</h3><p>Rational Running is coming to Lewiston on Sunday, April 7! Find a local business that is willing to sponsor you to run in this fundraising event. The more people who run, the more will be raised!</p><p>All of the money raised by Rational Running events is used to support local food drives. The proceeds from this event will go to the Lewiston Soup Kitchen. Volunteering to participate in this event as either a runner or an assistant coordinator also counts as community service time. See a Soup Kitchen representative to get a validation signature.</p><p>The race will be held at Lewiston High School on its outdoor track. Anyone who lives nearby and is not participating in the event is encouraged to come and cheer on the runners. A check-in booth will be set up by the north side of the bleachers. The booth will also be selling memorabilia t-shirts. Also, volunteers will hand out flyers that feature the names of each runner and all of his or her sponsors.</p><p>For more information about volunteering or making a donation to the Lewiston Soup Kitchen, please visit www.lewistonrationalrunning.org.</p>"],"vi":"Rational Running\n\nRational Running sẽ đến Lewiston vào Chủ Nhật 7/4! Hãy tìm một doanh nghiệp địa phương sẵn sàng tài trợ để bạn chạy trong sự kiện gây quỹ này. Càng nhiều người chạy, quỹ quyên được càng nhiều!\n\nToàn bộ số tiền từ các sự kiện Rational Running dùng để hỗ trợ các đợt quyên góp thực phẩm địa phương. Tiền thu từ sự kiện lần này sẽ dành cho Bếp ăn từ thiện Lewiston. Tình nguyện tham gia với vai trò người chạy hoặc trợ lý điều phối cũng được tính là giờ phục vụ cộng đồng. Hãy gặp đại diện của Bếp ăn để được ký xác nhận.\n\nCuộc chạy diễn ra trên đường chạy ngoài trời của trường Trung học Lewiston. Người dân sống gần đó không tham gia chạy được khuyến khích đến cổ vũ. Quầy điểm danh đặt ở phía bắc khán đài, quầy cũng bán áo phông lưu niệm. Ngoài ra, tình nguyện viên sẽ phát tờ rơi có tên từng người chạy và tất cả nhà tài trợ của họ.\n\nThông tin về tình nguyện hoặc quyên góp cho Bếp ăn từ thiện Lewiston, xem tại www.lewistonrationalrunning.org.","qs":[{"n":161,"q":"What is the main purpose of the notice?","qvi":"Mục đích chính của thông báo là gì?","opts":["To encourage people to exercise regularly","To announce a policy change","To promote a charity event","To profile a local business"],"ans":"C","xp":"Thông báo giới thiệu cuộc chạy 'fundraising event', tiền dùng cho bếp ăn từ thiện → quảng bá sự kiện từ thiện → (C)."},{"n":162,"q":"What most likely is Lewiston Soup Kitchen?","qvi":"Lewiston Soup Kitchen nhiều khả năng là gì?","opts":["A restaurant","A food bank","An animal shelter","A farm"],"ans":"B","xp":"'money raised... is used to support local food drives. The proceeds from this event will go to the Lewiston Soup Kitchen' → nơi phát thực phẩm từ thiện → (B)."},{"n":163,"q":"What is mentioned about participating runners?","qvi":"Điều gì được nhắc đến về người tham gia chạy?","opts":["They receive official recognition for participating.","They are required to pay a registration fee.","They are expected to attend an orientation.","They will be given a free t-shirt."],"ans":"A","xp":"'Volunteering... as either a runner... also counts as community service time. See a Soup Kitchen representative to get a validation signature' → được xác nhận chính thức → (A). (D) áo phông được bán, không tặng."},{"n":164,"q":"Where can attendees learn more about event sponsors?","qvi":"Người tham dự có thể biết thêm về nhà tài trợ ở đâu?","opts":["From a Web site","From a registration booth","From an event pamphlet","From a local newspaper"],"ans":"C","xp":"'volunteers will hand out flyers that feature the names of each runner and all of his or her sponsors' → tờ rơi của sự kiện → (C). (A) trang web chỉ nói về tình nguyện và quyên góp."}]},{"ns":[165,167],"head":"Questions 165-167 refer to the following letter.","passages":["<p>Fitness Magazine<br>PO Box 51854<br>Denver, CO 80907</p><p>3 September</p><p>Jacquie Berman<br>1872 Berry Street<br>Colorado Springs, CO 80903</p><p>Dear Ms. Berman,</p><p>Congratulations on renewing your subscription to Fitness Magazine for another year! Your renewal also qualifies you for a free trial subscription to any other magazine run by our publisher. That's two months longer than normal four-month trial periods. Enclosed you can find a full list of our publisher's magazines.</p><p>Now that you have been reading our magazine for a year, we would like to hear from you. Please fill out the survey on the back side of this page and return it to us. For your convenience, we included a pre-addressed postage-paid envelope so that you don't have to go to the post office.</p><p>Sincerely,<br>Michael Boles<br>Customer Service Representative</p>"],"vi":"Fitness Magazine, hộp thư 51854, Denver – ngày 3/9\nGửi chị Jacquie Berman, 1872 Berry Street, Colorado Springs\n\nKính gửi chị Berman,\n\nChúc mừng chị đã gia hạn đăng ký tạp chí Fitness Magazine thêm một năm! Việc gia hạn còn giúp chị được đọc thử miễn phí bất kỳ tạp chí nào khác của nhà xuất bản chúng tôi. Thời gian đọc thử dài hơn hai tháng so với bốn tháng thông thường. Kèm theo thư là danh sách đầy đủ các tạp chí của nhà xuất bản.\n\nChị đã đọc tạp chí của chúng tôi được một năm, chúng tôi muốn nghe ý kiến của chị. Vui lòng điền phiếu khảo sát ở mặt sau trang này và gửi lại. Để tiện cho chị, chúng tôi gửi kèm phong bì đã ghi sẵn địa chỉ và trả cước, chị không cần ra bưu điện.\n\nTrân trọng,\nMichael Boles – Nhân viên chăm sóc khách hàng","qs":[{"n":165,"q":"How long can Ms. Berman receive a free magazine?","qvi":"Chị Berman được nhận tạp chí miễn phí trong bao lâu?","opts":["For 3 months","For 4 months","For 6 months","For 12 months"],"ans":"C","xp":"'two months longer than normal four-month trial periods' → 4 + 2 = 6 tháng → (C)."},{"n":166,"q":"What is enclosed with the letter?","qvi":"Gửi kèm thư là gì?","opts":["A membership card","A list of periodicals","An order form","A meal voucher"],"ans":"B","xp":"'Enclosed you can find a full list of our publisher's magazines' → danh sách tạp chí (periodicals = ấn phẩm định kỳ) → (B)."},{"n":167,"q":"What is Ms. Berman asked to do?","qvi":"Chị Berman được đề nghị làm gì?","opts":["Make a payment on time","Mail back a feedback form","Write a comment online","Update her contact information"],"ans":"B","xp":"'Please fill out the survey... and return it to us... a pre-addressed postage-paid envelope' → gửi lại phiếu góp ý qua bưu điện → (B)."}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following online chat discussion.","passages":["<div class=\"msg\"><p><b>John Bautista [9:54 A.M.]</b></p><p>Are there any questions you have before this afternoon's planning meeting? I'm so pleased that Eunha Baek agreed to give a talk at our museum.</p></div><div class=\"msg\"><p><b>Satya Kamei [9:55 A.M.]</b></p><p>Me too. I've read several of her studies in journals, and I'm looking forward to hearing more about her research. The Marshall Center agreed to let us rent the hall for half off the usual rate.</p></div><div class=\"msg\"><p><b>Kun Quan [9:56 A.M.]</b></p><p>That's wonderful news!</p></div><div class=\"msg\"><p><b>Maura Genovesi [9:57 A.M.]</b></p><p>Yes, it is! I didn't think they would go for it.</p></div><div class=\"msg\"><p><b>Satya Kamei [9:59 A.M.]</b></p><p>Well, since it's a weekday, they didn't think they'd get a booking at the standard rate. Everything is coming together perfectly, isn't it?</p></div><div class=\"msg\"><p><b>John Bautista [10:01 A.M.]</b></p><p>Yes and no. I just found out that the Regional Music Association will hold a rock festival at Flynn Auditorium on the same night. People will be highly interested in that.</p></div><div class=\"msg\"><p><b>Kun Quan [10:02 A.M.]</b></p><p>That just means we need to promote our event more heavily. I can contact the editor of the Stoneybrook Times to see if we can get some free news coverage.</p></div><div class=\"msg\"><p><b>John Bautista [10:03 A.M.]</b></p><p>Thank you! Let's have Renee Abraham cater the refreshments again. She did a great job last time.</p></div><div class=\"msg\"><p><b>Maura Genovesi [10:06 A.M.]</b></p><p>Great idea. I'll call her before our meeting to see if she is available.</p></div>"],"vi":"John Bautista (9:54): Mọi người có câu hỏi gì trước buổi họp lên kế hoạch chiều nay không? Tôi rất vui vì Eunha Baek đã nhận lời đến bảo tàng mình nói chuyện.\nSatya Kamei (9:55): Tôi cũng vậy. Tôi đã đọc vài nghiên cứu của bà ấy trên tạp chí chuyên ngành và rất mong được nghe thêm về công trình của bà. Trung tâm Marshall đồng ý cho mình thuê hội trường với giá giảm một nửa.\nKun Quan (9:56): Tin tuyệt quá!\nMaura Genovesi (9:57): Đúng vậy! Tôi không nghĩ họ sẽ đồng ý.\nSatya Kamei (9:59): À, vì là ngày thường nên họ không nghĩ sẽ có ai thuê với giá gốc. Mọi thứ đang suôn sẻ, phải không?\nJohn Bautista (10:01): Vừa đúng vừa không. Tôi vừa biết Hiệp hội Âm nhạc Khu vực sẽ tổ chức lễ hội nhạc rock ở thính phòng Flynn cùng tối đó. Mọi người sẽ rất quan tâm đến sự kiện đó.\nKun Quan (10:02): Vậy thì mình cần quảng bá sự kiện mạnh hơn. Tôi có thể liên hệ biên tập viên báo Stoneybrook Times xem có được đưa tin miễn phí không.\nJohn Bautista (10:03): Cảm ơn anh! Mình lại nhờ Renee Abraham lo đồ ăn nhẹ nhé. Lần trước cô ấy làm rất tốt.\nMaura Genovesi (10:06): Ý hay. Tôi sẽ gọi cho cô ấy trước buổi họp xem cô ấy có rảnh không.","qs":[{"n":168,"q":"What event are the participants in the discussion organizing?","qvi":"Những người trò chuyện đang tổ chức sự kiện gì?","opts":["A music festival","An awards ceremony","An academic lecture","A museum grand opening"],"ans":"C","xp":"'Eunha Baek agreed to give a talk at our museum'; 'I've read several of her studies in journals... hearing more about her research' → buổi nói chuyện học thuật → (C). (A) lễ hội nhạc rock là sự kiện cạnh tranh."},{"n":169,"q":"At 9:57 A.M., what does Ms. Genovesi most likely mean when she writes, \"I didn't think they would go for it\"?","qvi":"Lúc 9:57, cô Genovesi có ý gì khi viết \"Tôi không nghĩ họ sẽ đồng ý\"?","opts":["She did not think the city would allow the event to be held.","She is surprised that a venue wasn't booked.","She thought a committee would elect someone else.","She doubted that a discount rate would be given."],"ans":"D","xp":"Ngay trước đó: 'The Marshall Center agreed to let us rent the hall for half off the usual rate' → cô không nghĩ họ đồng ý giảm giá → (D)."},{"n":170,"q":"What does Mr. Bautista think will happen?","qvi":"Ông Bautista nghĩ điều gì sẽ xảy ra?","opts":["A competing event will draw a lot of people.","A newspaper will be delivered early.","A crowd will be difficult to handle.","A promotion will be given to a coworker."],"ans":"A","xp":"'the Regional Music Association will hold a rock festival... on the same night. People will be highly interested in that' → sự kiện cạnh tranh thu hút nhiều người → (A)."},{"n":171,"q":"Who most likely will Ms. Genovesi contact today?","qvi":"Hôm nay cô Genovesi nhiều khả năng sẽ liên hệ ai?","opts":["A city official","A reporter","A caterer","A musician"],"ans":"C","xp":"John: 'Let's have Renee Abraham cater the refreshments again'; Maura: 'I'll call her before our meeting' → người cung cấp đồ ăn → (C). (B) phóng viên là Kun Quan liên hệ."}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following notice.","passages":["<h3>NOTICE TO ALL HIGHTOWN LITHO CUSTOMERS:</h3><p>From October 11 to 14, the largest machine (DC 10506) at the Rockford branch will be out of service due to regular maintenance and upgrades being made by the manufacturer. These adjustments will help us to improve our turnaround time on large orders by up to 15%. <span class=\"pos\">[1]</span> However, this will mean that the following services will be temporarily unavailable in Rockford during that time: A0 &amp; A1 copies, banners (both cloth and vinyl), billboard posters, and plastic signage larger than A2. There will be no change to operations in Cedar Falls and Westerville. <span class=\"pos\">[2]</span></p><p>We are still accepting print jobs for the above types, but they will all be processed at our Cedar Falls branch. Shipping charges usually apply when work is outsourced to another branch, but these will be waived during the maintenance work. <span class=\"pos\">[3]</span></p><p>We expect normal service to resume in Rockford from October 15. <span class=\"pos\">[4]</span> Customers should speak to one of our representatives to see how this affects requested projects or e-mail our headquarters at customerservices@hightownlitho.com. Customers may also visit www.hightownlitho.com for more information.</p>"],"vi":"THÔNG BÁO GỬI TẤT CẢ KHÁCH HÀNG HIGHTOWN LITHO:\n\nTừ 11 đến 14/10, máy lớn nhất (DC 10506) ở chi nhánh Rockford sẽ ngừng hoạt động để nhà sản xuất bảo trì định kỳ và nâng cấp. Những điều chỉnh này giúp rút ngắn thời gian hoàn thành đơn hàng lớn tới 15%. Tuy nhiên, trong thời gian đó các dịch vụ sau tạm ngừng ở Rockford: bản in khổ A0 & A1, băng rôn (vải và nhựa vinyl), áp phích biển quảng cáo lớn và biển nhựa lớn hơn khổ A2. Hoạt động ở Cedar Falls và Westerville không thay đổi.\n\nChúng tôi vẫn nhận in các loại trên, nhưng tất cả sẽ được xử lý ở chi nhánh Cedar Falls. Thông thường có tính phí vận chuyển khi chuyển việc sang chi nhánh khác, nhưng phí này được miễn trong thời gian bảo trì. Trong trường hợp này, xin vui lòng chờ thêm một ngày giao hàng.\n\nDự kiến chi nhánh Rockford hoạt động bình thường lại từ 15/10. Khách hàng nên trao đổi với nhân viên của chúng tôi để biết điều này ảnh hưởng thế nào đến đơn hàng, hoặc e-mail trụ sở customerservices@hightownlitho.com. Xem thêm tại www.hightownlitho.com.","qs":[{"n":172,"q":"What is the purpose of the notice?","qvi":"Mục đích của thông báo là gì?","opts":["To announce a temporary store closure","To introduce a newly available service","To announce the opening of an additional branch","To inform customers of reduced services"],"ans":"D","xp":"'the following services will be temporarily unavailable in Rockford' → báo một số dịch vụ tạm ngừng → (D). (A) chi nhánh không đóng cửa, chỉ một máy ngừng."},{"n":173,"q":"What advantage does the company hope to gain?","qvi":"Công ty hy vọng có được lợi ích gì?","opts":["An increase in printing speed","An expanded customer base","A location for a new outlet","A decrease in prices"],"ans":"A","xp":"'These adjustments will help us to improve our turnaround time on large orders by up to 15%' → in nhanh hơn → (A)."},{"n":174,"q":"Where will orders for billboard posters be processed from October 11 to 14?","qvi":"Từ 11 đến 14/10, đơn in áp phích biển quảng cáo sẽ được xử lý ở đâu?","opts":["At the headquarters","At the Rockford branch","At the Cedar Falls branch","At the Westerville branch"],"ans":"C","xp":"'We are still accepting print jobs for the above types, but they will all be processed at our Cedar Falls branch' → (C)."},{"n":175,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? \"Please allow an additional day for deliveries in this case.\"","qvi":"Câu sau phù hợp nhất ở vị trí nào? \"Trong trường hợp này, xin vui lòng chờ thêm một ngày giao hàng.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"C","xp":"'in this case' = khi việc in được chuyển sang chi nhánh khác và vận chuyển về → đặt sau câu nói về phí vận chuyển khi chuyển việc sang chi nhánh khác, vị trí [3] → (C)."}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following advertisement and e-mail.","passages":["<h3>Pearl Beach Vacation Rentals</h3><p>Take a few days to escape from the stress of daily life and enjoy relaxing in a rental house located right on Pearl Beach! Choose from one of the options below. Whether you're coming with your family members or a group of friends, we have a place to match your needs, all with beachfront views.</p><table><tr><th>Rental Property</th><th>Features</th><th>Daily Rate ($)</th></tr><tr><td>Couple Suite</td><td>1 Bedroom (2 guests); Buffet Passes</td><td>140</td></tr><tr><td>Honeymoon Suite</td><td>1 Bedroom (2 guests); Room service on Request</td><td>170</td></tr><tr><td>Family Retreat</td><td>2 Bedrooms (up to 4 guests); Barbecue Pit</td><td>260</td></tr><tr><td>Party House</td><td>3 Bedrooms (6 guests); Barbecue Pit</td><td>310</td></tr></table><p>Although rooms can accommodate more than the suggested number of guests, there is a $20 per person per night fee. Extra beds are available for extra costs. Food menus differ based on the season.</p><p>*Any child under the age of 4 will be exempt from all extra fees.</p>","<div class=\"hdr\"><p><b>TO:</b> Pearl Beach Vacation Rentals &lt;custserv@pbvr.com&gt;</p><p><b>FROM:</b> John Woodall &lt;j.woodall@jmail.net&gt;</p><p><b>DATE:</b> 8 March</p><p><b>SUBJECT:</b> Rental questions</p></div><p>I plan on taking a trip with my wife and son this summer, and we are interested in spending a few days at one of your properties. We have stayed at other resorts run by your parent company, Global Resorts, and really enjoyed them. There are a few questions I have about your properties before I make a reservation, though. First, are we allowed to have an extra person in the room? Our son is only 2 years old and still sleeps in the same room with us. Also, we would prefer to have our meals in private in the guest room. Finally, I would like to know if the area your resort is located in has stores and restaurants to wander around at on foot or if your resort offers a shuttle bus service. I have a tight budget and want to save some money on transportation such as renting a car or taking a taxi.</p><p>Thank you in advance.</p><p>John Woodall</p>"],"vi":"Nhà nghỉ cho thuê Pearl Beach\nHãy dành vài ngày thoát khỏi căng thẳng thường ngày và thư giãn trong căn nhà cho thuê ngay trên bãi biển Pearl! Chọn một trong các lựa chọn dưới đây. Dù đi cùng gia đình hay nhóm bạn, chúng tôi đều có chỗ phù hợp, tất cả đều nhìn thẳng ra biển.\nCouple Suite: 1 phòng ngủ (2 khách), vé ăn buffet – 140 đô/ngày | Honeymoon Suite: 1 phòng ngủ (2 khách), phục vụ ăn tại phòng theo yêu cầu – 170 đô | Family Retreat: 2 phòng ngủ (tối đa 4 khách), lò nướng BBQ – 260 đô | Party House: 3 phòng ngủ (6 khách), lò nướng BBQ – 310 đô.\nPhòng có thể ở nhiều hơn số khách đề xuất nhưng tính thêm 20 đô mỗi người mỗi đêm. Có giường phụ với chi phí thêm. Thực đơn thay đổi theo mùa.\n*Trẻ dưới 4 tuổi được miễn mọi khoản phụ phí.\n\nNgười nhận: Pearl Beach Vacation Rentals | Người gửi: John Woodall | Ngày: 8/3 | Chủ đề: Câu hỏi về thuê nhà\nHè này tôi định đi du lịch với vợ và con trai, và muốn ở vài ngày tại một căn nhà của quý công ty. Chúng tôi từng ở các khu nghỉ khác của công ty mẹ Global Resorts và rất thích. Trước khi đặt, tôi có vài câu hỏi. Thứ nhất, có được thêm một người trong phòng không? Con trai tôi mới 2 tuổi và vẫn ngủ cùng phòng với chúng tôi. Ngoài ra, chúng tôi muốn ăn riêng trong phòng. Cuối cùng, tôi muốn biết quanh khu nghỉ có cửa hàng, nhà hàng để đi bộ dạo không, hay khu nghỉ có xe đưa đón không. Ngân sách của tôi eo hẹp nên muốn tiết kiệm tiền đi lại như thuê xe hay đi taxi.\nCảm ơn trước. – John Woodall","qs":[{"n":176,"q":"What feature do the properties of Pearl Beach Vacation Rentals have in common?","qvi":"Các căn nhà của Pearl Beach Vacation Rentals có điểm chung gì?","opts":["The number of bedrooms","The views that they have","The meal options","The suggested number of guests"],"ans":"B","xp":"'we have a place to match your needs, all with beachfront views' → tất cả đều nhìn ra biển → (B)."},{"n":177,"q":"What kind of property will Mr. Woodall most likely rent?","qvi":"Ông Woodall nhiều khả năng sẽ thuê loại nào?","opts":["Couple Suite","Honeymoon Suite","Family Retreat","Party House"],"ans":"B","xp":"Hai vợ chồng + con 2 tuổi (dưới 4 tuổi được miễn phụ phí, ngủ chung phòng) và muốn 'have our meals in private in the guest room' → căn 1 phòng ngủ có 'Room service on Request' là Honeymoon Suite → (B)."},{"n":178,"q":"What is stated about Pearl Beach Vacation Rentals?","qvi":"Điều gì được nêu về Pearl Beach Vacation Rentals?","opts":["It is a subsidiary company.","It normally has a wait list.","It has a famous kitchen staff.","It only operates during the summer."],"ans":"A","xp":"E-mail: 'other resorts run by your parent company, Global Resorts' → có công ty mẹ → là công ty con → (A)."},{"n":179,"q":"What is implied about Mr. Woodall?","qvi":"Có thể suy ra điều gì về ông Woodall?","opts":["He travels for business often.","He won't pay for an extra bed.","He prefers to cook meals himself.","He has been to Pearl Beach before."],"ans":"B","xp":"Con ông 2 tuổi; quảng cáo: 'Any child under the age of 4 will be exempt from all extra fees' → ông không phải trả phụ phí, kể cả giường phụ → (B). (D) ông từng ở khu nghỉ khác của công ty mẹ, không phải Pearl Beach."},{"n":180,"q":"In the e-mail, what does Mr. Woodall suggest about his vacation plans?","qvi":"Trong e-mail, ông Woodall gợi ý gì về kế hoạch nghỉ?","opts":["He wants to spend time on the beach.","He is going to attend social events.","He will reserve a morning flight.","He does not intend to rent a car."],"ans":"D","xp":"'I have a tight budget and want to save some money on transportation such as renting a car or taking a taxi' → không định thuê xe → (D)."}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following flyer and online form.","passages":["<h3>Bristow Cultural Museum</h3><p>Sign up for a membership at Bristow Cultural Museum to enjoy a variety of benefits. For a small monthly fee of $25, you can:</p><ul><li>Receive a copy of the museum's monthly newsletter</li><li>Receive daily \"This Day In History\" text messages</li><li>Get early access to cultural event tickets, as well as $5 off any event ticket (Normally $20)</li><li>Enter museum exhibit areas for free (Normally $10)</li></ul><p>Cultural events such as theatrical or musical performances are held every weekend. Visit the museum's Web site for a schedule of upcoming events. Weather permitting, events are held outdoors from April to September. All outdoor cultural events are provided to all museum visitors for free.</p>","<h3>Bristow Cultural Museum Event Tickets</h3><p>bmuseum.org/tickets</p><table><tr><td>Event Date:</td><td>7 February</td></tr><tr><td>Event:</td><td>Traditional Russian Dance</td></tr><tr><td>Ticket Price:</td><td>$15.00</td></tr><tr><td>Number of Tickets:</td><td>2</td></tr><tr><td>Total Cost:</td><td>$30.00</td></tr></table><p><b>Personal Information</b></p><table><tr><td>Name:</td><td>Elias Dorsey</td></tr><tr><td>Address:</td><td>944 Ridge Drive, Bristow</td></tr><tr><td>Phone Number:</td><td>555-8592</td></tr><tr><td>Card Type:</td><td>Visa</td></tr><tr><td>Name On Card:</td><td>ELIAS DORSEY</td></tr><tr><td>Card Number:</td><td>xxxx-xxxx-xxxx-7021</td></tr></table><p>I agree to the terms of membership: ✓</p>"],"vi":"Bảo tàng Văn hóa Bristow\nĐăng ký hội viên Bảo tàng Văn hóa Bristow để nhận nhiều quyền lợi. Chỉ với 25 đô mỗi tháng, bạn được:\n- Nhận bản tin hằng tháng của bảo tàng\n- Nhận tin nhắn \"Ngày này năm xưa\" mỗi ngày\n- Mua vé sự kiện văn hóa sớm, giảm 5 đô mỗi vé (giá thường 20 đô)\n- Vào các khu trưng bày miễn phí (giá thường 10 đô)\nSự kiện văn hóa như kịch, âm nhạc diễn ra mỗi cuối tuần. Xem lịch sự kiện trên trang web bảo tàng. Nếu thời tiết cho phép, sự kiện được tổ chức ngoài trời từ tháng 4 đến tháng 9. Mọi sự kiện ngoài trời đều miễn phí cho mọi khách tham quan.\n\nVé sự kiện – Bảo tàng Văn hóa Bristow: Ngày 7/2 | Sự kiện: Múa truyền thống Nga | Giá vé: 15 đô | Số vé: 2 | Tổng: 30 đô\nThông tin cá nhân: Elias Dorsey, 944 Ridge Drive, Bristow, 555-8592 | Thẻ Visa ****7021 | Tôi đồng ý với điều khoản hội viên: ✓","qs":[{"n":181,"q":"What is the main purpose of the flyer?","qvi":"Mục đích chính của tờ rơi là gì?","opts":["To advertise a performance","To introduce a new exhibition","To recruit qualified employees","To publicize a membership program"],"ans":"D","xp":"'Sign up for a membership... to enjoy a variety of benefits' → quảng bá chương trình hội viên → (D)."},{"n":182,"q":"What is implied about Bristow Cultural Museum?","qvi":"Có thể suy ra điều gì về Bảo tàng Văn hóa Bristow?","opts":["It has an outdoor stage.","It offers free memberships.","It changes exhibits monthly.","It employs multilingual staff members."],"ans":"A","xp":"'events are held outdoors from April to September' (kịch, âm nhạc ngoài trời) → bảo tàng có sân khấu ngoài trời → (A). (B) hội viên trả 25 đô/tháng."},{"n":183,"q":"What is NOT stated about cultural events?","qvi":"Điều gì KHÔNG được nêu về các sự kiện văn hóa?","opts":["They are held throughout the year.","Their schedules are posted online.","Members get discounted tickets for them.","All of them are musical concerts."],"ans":"D","xp":"(A) 'held every weekend'; (B) lịch trên trang web; (C) hội viên giảm 5 đô. Sự kiện gồm 'theatrical or musical performances', không phải toàn hòa nhạc → (D)."},{"n":184,"q":"What is most likely true about Mr. Dorsey?","qvi":"Điều gì nhiều khả năng đúng về ông Dorsey?","opts":["He is an employee of Bristow Cultural Museum.","He gets a discount when viewing exhibits.","He pays $25 every month.","He has recently been to Russia."],"ans":"C","xp":"Ông mua vé giá 15 đô (giá thường 20 đô, hội viên giảm 5 đô) và đánh dấu đồng ý điều khoản hội viên → ông là hội viên, trả 25 đô mỗi tháng → (C). (B) hội viên vào xem miễn phí, không phải giảm giá."},{"n":185,"q":"What is suggested about the event Traditional Russian Dance?","qvi":"Có thể suy ra điều gì về sự kiện Múa truyền thống Nga?","opts":["Its tickets have been sold out.","It was originally scheduled to be held outdoors.","It will be held indoors.","All of the dancers are coming from Russia."],"ans":"C","xp":"Sự kiện ngày 7/2; tờ rơi: chỉ tổ chức ngoài trời từ tháng 4 đến tháng 9 (và sự kiện ngoài trời miễn phí, còn vé này phải trả tiền) → tổ chức trong nhà → (C)."}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following letters and invoice.","passages":["<p>Eastland Sports Memorabilia<br>623 Stafford Road<br>Eastland, TX 76448</p><p>July 18</p><p>To Whom It May Concern:</p><p>I have been an avid collector of baseball cards and collectibles for approximately seven years. I was pleased to come across your shop recently while visiting some relatives in Eastland. I purchased several items at that time. However, when I got home and took a closer look at the items, I became concerned that one of them was fake. The signature on the baseball autographed by Alfonzo Deluca is quite different from those on the other signed posters and baseball cards that I have of him. Of course, if this is not his real signature on the ball, it is completely worthless to a collector like me. I would like you to look into this matter as soon as possible. I have enclosed a copy of the invoice for your convenience. I await your response.</p><p>Sincerely,<br>Luis Sullivan</p>","<h3>CUSTOMER INVOICE • EASTLAND SPORTS MEMORABILIA</h3><p>623 Stafford Road, Eastland, TX 76448 • 254-555-6211</p><p><b>Date:</b> June 29 <b>Customer:</b> Luis Sullivan</p><table><tr><th>Item #</th><th>Description</th><th>Price</th></tr><tr><td>1094</td><td>Baseball display case (empty, wooden base, glass sides)</td><td>$49.99</td></tr><tr><td>1722</td><td>Leather-bound baseball card binder (displays 9 cards/page)</td><td>$39.99</td></tr><tr><td>2948</td><td>Wildcats Championship Baseball signed by Alfonzo Deluca</td><td>$495.99</td></tr><tr><td>2659</td><td>Wildcats Stadium Home Plate (1994 season)</td><td>$565.99</td></tr><tr><td>3029</td><td>Eagles batting practice jersey worn by Alex McManus (1999 season)</td><td>$295.99</td></tr><tr><td></td><td>Total</td><td>$1,447.95</td></tr></table><p>Do you have sports memorabilia or collectible items to sell? Call us today to get a quote.</p>","<p>Luis Sullivan<br>3271 Troy Avenue<br>Whitestone, NY 11357</p><p>July 23</p><p>Dear Mr. Sullivan,</p><p>Regarding your most recent purchase from Eastland Sports Memorabilia, I can assure you that all of our items are certified by an independent agency, and the certificate for the item you mentioned is enclosed. For baseballs, sometimes the signature is slightly different because of the difficulty of writing on a rounded surface. If you still feel that the purchase is unsatisfactory, we would be happy to refund the full price. However, in this case I would recommend taking action quickly because we can only process returns within 45 days of the purchase date.</p><p>No matter what you decide to do, I will send you an additional baseball display case for you to keep as our gift.</p><p>Sincerely,<br>William Mason</p>"],"vi":"Gửi cửa hàng Eastland Sports Memorabilia, 623 Stafford Road, Eastland, Texas – ngày 18/7\nKính gửi Quý cửa hàng, tôi là người sưu tầm thẻ bóng chày và đồ lưu niệm say mê khoảng bảy năm nay. Gần đây tôi rất vui khi tình cờ thấy cửa hàng của quý vị lúc đến thăm họ hàng ở Eastland, và đã mua vài món. Nhưng khi về nhà xem kỹ, tôi lo một món là đồ giả. Chữ ký trên quả bóng có chữ ký của Alfonzo Deluca khác hẳn chữ ký trên các áp phích và thẻ bóng chày có chữ ký của anh ấy mà tôi đang có. Dĩ nhiên, nếu đây không phải chữ ký thật thì quả bóng hoàn toàn vô giá trị với người sưu tầm như tôi. Mong quý vị xem xét việc này sớm nhất có thể. Tôi gửi kèm bản sao hóa đơn để tiện theo dõi. Tôi chờ phản hồi. – Luis Sullivan\n\nHÓA ĐƠN KHÁCH HÀNG – EASTLAND SPORTS MEMORABILIA. Ngày: 29/6 | Khách: Luis Sullivan\n1094 Hộp trưng bày bóng chày (trống, đế gỗ, thành kính) 49,99 đô | 1722 Bìa đựng thẻ bóng chày bọc da (9 thẻ/trang) 39,99 đô | 2948 Bóng vô địch Wildcats có chữ ký Alfonzo Deluca 495,99 đô | 2659 Tấm đệm Home Plate sân Wildcats (mùa 1994) 565,99 đô | 3029 Áo tập đánh bóng đội Eagles của Alex McManus (mùa 1999) 295,99 đô | Tổng 1.447,95 đô\nBạn có đồ lưu niệm thể thao hay đồ sưu tầm muốn bán? Gọi cho chúng tôi ngay để được báo giá.\n\nGửi ông Luis Sullivan, 3271 Troy Avenue, Whitestone, New York – ngày 23/7\nKính gửi ông Sullivan, về món hàng ông vừa mua ở Eastland Sports Memorabilia, tôi cam đoan mọi sản phẩm của chúng tôi đều được một tổ chức độc lập chứng nhận, và giấy chứng nhận của món ông nhắc đến được gửi kèm. Với bóng chày, đôi khi chữ ký hơi khác vì khó viết trên bề mặt cong. Nếu ông vẫn chưa hài lòng, chúng tôi sẵn lòng hoàn lại toàn bộ tiền. Tuy nhiên, trong trường hợp đó tôi khuyên ông nên làm nhanh vì chúng tôi chỉ nhận trả hàng trong vòng 45 ngày kể từ ngày mua.\nDù ông quyết định thế nào, tôi cũng sẽ gửi tặng ông thêm một hộp trưng bày bóng chày. – William Mason","qs":[{"n":186,"q":"What is the purpose of Mr. Sullivan's letter?","qvi":"Mục đích thư của ông Sullivan là gì?","opts":["To complain about a shipping problem","To report some broken merchandise","To request a refund for an overcharge on a bill","To question a product's authenticity"],"ans":"D","xp":"'I became concerned that one of them was fake' → nghi ngờ hàng thật/giả → (D)."},{"n":187,"q":"Which item does Mr. Mason offer to refund?","qvi":"Ông Mason đề nghị hoàn tiền món nào?","opts":["1094","2948","2659","3029"],"ans":"B","xp":"Món bị nghi là quả bóng có chữ ký Alfonzo Deluca; hóa đơn: '2948 Wildcats Championship Baseball signed by Alfonzo Deluca' → (B)."},{"n":188,"q":"What is implied about Eastland Sports Memorabilia?","qvi":"Có thể suy ra điều gì về Eastland Sports Memorabilia?","opts":["It has a branch near Mr. Sullivan's home.","It offers an expedited shipping option.","It purchases used items from customers.","It has been open for about seven years."],"ans":"C","xp":"Hóa đơn: 'Do you have sports memorabilia or collectible items to sell? Call us today to get a quote' → cửa hàng mua lại đồ của khách → (C). (D) bảy năm là thời gian ông Sullivan sưu tầm."},{"n":189,"q":"What is indicated by Mr. Mason?","qvi":"Ông Mason cho biết điều gì?","opts":["A receipt should be included with a request.","Returns must be made in person at the store.","The price of an item has recently changed.","A solution is available for a limited time."],"ans":"D","xp":"'we can only process returns within 45 days of the purchase date' → giải pháp hoàn tiền có thời hạn → (D)."},{"n":190,"q":"What is the value of the item that will be sent to Mr. Sullivan for free?","qvi":"Món quà gửi tặng ông Sullivan trị giá bao nhiêu?","opts":["$39.99","$49.99","$295.99","$495.99"],"ans":"B","xp":"Ông Mason: 'I will send you an additional baseball display case'; hóa đơn: 'Baseball display case... $49.99' → (B)."}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following memo, e-mail, and article.","passages":["<div class=\"hdr\"><p><b>To:</b> All Balentine Labs Employees</p><p><b>From:</b> Saeko Nagao</p><p><b>Re:</b> Please read</p><p><b>Date:</b> March 3</p></div><p>A group of chemistry students from the Lavelle Institute is scheduled to visit our headquarters on Thursday, March 17. I want to make sure that you don't forget our company regulations on visitors, the same ones discussed prior to the press event last month. Employees may answer general questions about the work duties and our existing products on the market. For the sake of company privacy, you are not to discuss any current projects. It is important that we keep our trade secrets secure. During the visit, the site manager will give the students a tour, and then they will attend a question-and-answer session led by the director of the research department. Your cooperation is appreciated.</p>","<div class=\"hdr\"><p><b>To:</b> Saeko Nagao &lt;saeko.nagao@balentinelabs.com&gt;</p><p><b>From:</b> Karen Dupree &lt;dupreek@lavelleinstitute.edu&gt;</p><p><b>Date:</b> March 10</p><p><b>Subject:</b> Upcoming Visit</p></div><p>Dear Ms. Nagao,</p><p>I regret to inform you that my class will not be able to visit your facility on the day we had planned. Unfortunately, there were some scheduling problems. We would still very much like to see your operations, if possible. We are available for any of the following: Tuesday, March 15 (9-noon), Friday, March 18 (2-5), or Saturday, March 19 (1-4). Please let me know if any of these time slots work with your schedule, and thank you for accommodating us.</p><p>Warmest regards,<br>Karen Dupree<br>Instructor, Chemistry Department, Lavelle Institute</p>","<h3>Lavelle Institute April Newsletter—Vol. 254</h3><h4>Students See Laboratory Jobs in Action</h4><p>By Corey Ramey</p><p>A group of undergraduates from Lavelle Institute's chemistry department, along with instructor Karen Dupree, visited Balentine Labs last month. They toured the facility, saw equipment demonstrations, and learned about the operations there. Even though it was a weekend, the facility was still as busy as ever, as it is open seven days a week to accommodate time-sensitive research. \"I learned a great deal from the tour,\" said second-year student Cynthia Lester.</p><p>\"We are particularly proud to show off our recently opened building extension,\" said Mira Prakash as she responded to inquiries from the group at a special session following the tour. \"Thanks to the new space, we are now running trials with patients right here at our headquarters. This is saving us a lot of time and hassle because we don't need to try to find clinic space for this purpose.\"</p>"],"vi":"Gửi: Toàn thể nhân viên Balentine Labs | Từ: Saeko Nagao | V/v: Xin đọc kỹ | Ngày: 3/3\nMột nhóm sinh viên hóa học của Viện Lavelle dự kiến đến thăm trụ sở chúng ta vào thứ Năm 17/3. Tôi muốn nhắc mọi người đừng quên quy định của công ty về khách tham quan, giống như đã bàn trước buổi họp báo tháng trước. Nhân viên có thể trả lời câu hỏi chung về công việc và các sản phẩm đang có trên thị trường. Để bảo mật, không được nói về các dự án hiện tại. Giữ bí mật kinh doanh là rất quan trọng. Trong chuyến thăm, quản lý cơ sở sẽ dẫn sinh viên tham quan, sau đó các em dự buổi hỏi đáp do trưởng phòng nghiên cứu chủ trì. Cảm ơn sự hợp tác của mọi người.\n\nNgười nhận: Saeko Nagao | Người gửi: Karen Dupree | Ngày: 10/3 | Chủ đề: Chuyến thăm sắp tới\nKính gửi bà Nagao, tôi rất tiếc phải báo lớp tôi không thể đến thăm vào ngày đã định do trục trặc lịch. Chúng tôi vẫn rất muốn tham quan nếu được. Chúng tôi có thể đến vào: thứ Ba 15/3 (9 giờ – trưa), thứ Sáu 18/3 (2–5 giờ chiều) hoặc thứ Bảy 19/3 (1–4 giờ chiều). Xin cho tôi biết khung giờ nào phù hợp, và cảm ơn bà đã sắp xếp. – Karen Dupree, giảng viên khoa Hóa, Viện Lavelle\n\nBản tin tháng 4 của Viện Lavelle – Số 254: Sinh viên tận mắt xem công việc phòng thí nghiệm – Corey Ramey\nTháng trước, một nhóm sinh viên khoa Hóa của Viện Lavelle cùng giảng viên Karen Dupree đã đến thăm Balentine Labs. Các em tham quan cơ sở, xem trình diễn thiết bị và tìm hiểu hoạt động ở đó. Dù là cuối tuần, cơ sở vẫn bận rộn như mọi ngày vì mở cửa bảy ngày một tuần phục vụ các nghiên cứu gấp. \"Em học được rất nhiều từ chuyến tham quan,\" sinh viên năm hai Cynthia Lester nói.\n\"Chúng tôi đặc biệt tự hào giới thiệu khu nhà mở rộng mới khánh thành,\" bà Mira Prakash nói khi trả lời câu hỏi của đoàn trong buổi hỏi đáp đặc biệt sau chuyến tham quan. \"Nhờ không gian mới, giờ chúng tôi thử nghiệm với bệnh nhân ngay tại trụ sở. Điều này tiết kiệm rất nhiều thời gian và rắc rối vì không phải đi tìm phòng khám cho việc này.\"","qs":[{"n":191,"q":"Why did Ms. Nagao send the memo?","qvi":"Vì sao bà Nagao gửi bản ghi nhớ?","opts":["To announce a regulation change","To ask for volunteers for a tour","To remind employees of a policy","To introduce a job opportunity"],"ans":"C","xp":"'I want to make sure that you don't forget our company regulations on visitors, the same ones discussed prior to the press event last month' → nhắc lại quy định → (C). (A) quy định không thay đổi."},{"n":192,"q":"In the memo, the word \"secure\" in paragraph 1, line 6, is closest in meaning to","qvi":"Trong bản ghi nhớ, từ \"secure\" ở đoạn 1, dòng 6 gần nghĩa nhất với","opts":["confident","closed","protected","fastened"],"ans":"C","xp":"'keep our trade secrets secure' = giữ bí mật kinh doanh an toàn, được bảo vệ → (C) protected."},{"n":193,"q":"When did Ms. Dupree's group most likely visit Balentine Labs?","qvi":"Nhóm của cô Dupree nhiều khả năng đến thăm Balentine Labs ngày nào?","opts":["March 15","March 17","March 18","March 19"],"ans":"D","xp":"E-mail đưa ba lựa chọn 15/3 (thứ Ba), 18/3 (thứ Sáu), 19/3 (thứ Bảy); bài báo: 'Even though it was a weekend' → thứ Bảy 19/3 → (D). (B) 17/3 là ngày cũ đã bị hủy."},{"n":194,"q":"What is implied about Ms. Prakash?","qvi":"Có thể suy ra điều gì về bà Prakash?","opts":["She is the site manager for Balentine Labs.","She has been in school for two years.","She is the head of a department.","She is planning another tour soon."],"ans":"C","xp":"Bài báo: bà Prakash trả lời câu hỏi 'at a special session following the tour'; bản ghi nhớ: buổi hỏi đáp sau tham quan 'led by the director of the research department' → bà là trưởng phòng → (C). (A) quản lý cơ sở là người dẫn tham quan."},{"n":195,"q":"What is suggested about Balentine Labs?","qvi":"Có thể suy ra điều gì về Balentine Labs?","opts":["It is conducting on-site trials with patients for the first time.","It exclusively hires Lavelle Institute graduates.","It has difficulty recruiting patients for its research.","It runs a free clinic to provide medical care."],"ans":"A","xp":"'Thanks to the new space, we are now running trials with patients right here at our headquarters... we don't need to try to find clinic space' → lần đầu thử nghiệm với bệnh nhân ngay tại trụ sở → (A)."}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following advertisement, form, and e-mail.","passages":["<h3>Morris Fabrics</h3><p>Don't replace your old furniture. Instead, why not have the worn fabric replaced by our skilled technicians at a fraction of the cost of buying new? Here at Morris Fabrics, we have been upholstering furniture with only the finest-quality materials for nearly twenty years. Our staff members are trained and managed to the highest standards, and we have an experienced crew that concentrates solely on working with chairs and sofas that are over one hundred years old.</p><p>For orders of five or more similar items, we will be offering a discount of 20% until the end of September. This is perfect for hotels and offices. Contact us at (302) 555-9898 or visit www.morrisfabrics.com for more information.</p>","<h3>Work Order #3299</h3><table><tr><td>Employee:</td><td>Holly Weston #145</td></tr><tr><td>Date:</td><td>September 23</td></tr><tr><td>Completion due:</td><td>September 25</td></tr><tr><td>Scheduled delivery date:</td><td>September 26</td></tr><tr><td>Customer name:</td><td>David Greaves</td></tr></table><p><b>Details:</b> 6 Mahogany Georgian-style chairs. Each to be stripped of all seating fabric. Replacement fabric Burgundy Felt (#134378) to be applied using standard pinning. Ensure double seam on the underside. Re-polish worn areas on front bar and arms. Check for loose crossbars on legs. Apply transparent adhesive, if required.</p>","<div class=\"hdr\"><p><b>To:</b> Morris Fabrics &lt;customerservices@morrisfabrics.com&gt;</p><p><b>From:</b> David Greaves</p><p><b>Date:</b> September 28</p><p><b>Subject:</b> Additional request</p></div><p>To Whom It May Concern:</p><p>I was extremely pleased with the quality of work on my most recent order, and I was pleasantly surprised to receive my chairs a day earlier than scheduled. The work done on them is fantastic, especially considering the price. Having had the chance to look at the chairs in place in my entrance hall, I now realize that the new covering does not go with the curtains I currently have. I was wondering if you sell fabric. If I could get an additional 36 yards of the same fabric, I could have curtains made that would be exactly the same as the chairs.</p><p>Please e-mail me back to arrange a time for me to come in and look at the fabric again, if it's available, as well as some other complementary options.</p><p>Yours sincerely,<br>David Greaves</p>"],"vi":"Morris Fabrics\nĐừng thay đồ nội thất cũ. Thay vào đó, sao không nhờ thợ lành nghề của chúng tôi thay lớp vải đã sờn với chi phí chỉ bằng một phần nhỏ so với mua mới? Tại Morris Fabrics, chúng tôi đã bọc lại đồ nội thất bằng vật liệu tốt nhất gần hai mươi năm nay. Nhân viên được đào tạo và quản lý theo tiêu chuẩn cao nhất, và chúng tôi có một đội giàu kinh nghiệm chuyên làm riêng với ghế và sofa hơn một trăm năm tuổi.\nĐơn từ năm món tương tự trở lên được giảm 20% đến hết tháng 9. Rất phù hợp cho khách sạn và văn phòng. Liên hệ (302) 555-9898 hoặc www.morrisfabrics.com.\n\nPhiếu công việc #3299 – Nhân viên: Holly Weston #145 | Ngày: 23/9 | Hạn hoàn thành: 25/9 | Ngày giao dự kiến: 26/9 | Khách: David Greaves\nChi tiết: 6 ghế gỗ gụ kiểu Georgian. Tháo hết vải bọc ghế. Bọc vải nỉ màu đỏ đô (#134378) bằng ghim tiêu chuẩn. Đảm bảo đường may đôi ở mặt dưới. Đánh bóng lại chỗ mòn ở thanh trước và tay vịn. Kiểm tra thanh ngang chân ghế bị lỏng. Dùng keo trong suốt nếu cần.\n\nNgười nhận: Morris Fabrics | Người gửi: David Greaves | Ngày: 28/9 | Chủ đề: Yêu cầu thêm\nKính gửi Quý công ty, tôi rất hài lòng với chất lượng đơn hàng vừa rồi, và bất ngờ vui vì nhận ghế sớm hơn dự kiến một ngày. Công việc tuyệt vời, nhất là so với giá tiền. Khi đặt ghế ở sảnh vào nhà, tôi nhận ra lớp vải mới không hợp với rèm cửa hiện tại. Không biết quý công ty có bán vải không. Nếu mua thêm được 36 thước cùng loại vải, tôi có thể may rèm giống hệt ghế.\nXin e-mail lại để hẹn giờ tôi đến xem vải lần nữa, nếu còn, cùng vài lựa chọn phối hợp khác. – David Greaves","qs":[{"n":196,"q":"What is suggested about Morris Fabrics?","qvi":"Có thể suy ra điều gì về Morris Fabrics?","opts":["It has a photo gallery of finished projects online.","It accepts used furniture for recycling.","It has a team that specializes in antique pieces.","It has recently changed ownership."],"ans":"C","xp":"'an experienced crew that concentrates solely on working with chairs and sofas that are over one hundred years old' → đội chuyên đồ cổ → (C)."},{"n":197,"q":"What is true about Mr. Greaves?","qvi":"Điều gì đúng về ông Greaves?","opts":["He works as an interior designer.","He got a bulk discount on his order.","He is an employee at a hotel.","He selected two fabrics for a project."],"ans":"B","xp":"Phiếu công việc: 6 ghế, ngày 23/9; quảng cáo: 'orders of five or more similar items... 20% until the end of September' → ông được giảm giá đơn số lượng lớn → (B)."},{"n":198,"q":"What does Mr. Greaves ask Morris Fabrics to do?","qvi":"Ông Greaves nhờ Morris Fabrics làm gì?","opts":["Send a fabric sample","Set up an appointment","Recommend some product styles","Put some curtains on reserve"],"ans":"B","xp":"'Please e-mail me back to arrange a time for me to come in and look at the fabric' → hẹn lịch đến xem → (B)."},{"n":199,"q":"In the e-mail, the phrase \"go with\" in paragraph 1, line 4, is closest in meaning to","qvi":"Trong e-mail, cụm \"go with\" ở đoạn 1, dòng 4 gần nghĩa nhất với","opts":["provide","match","accept","accompany"],"ans":"B","xp":"'the new covering does not go with the curtains' = không hợp với rèm → (B) match. (D) accompany là nghĩa 'đi cùng', không hợp ở đây."},{"n":200,"q":"When did Mr. Greaves receive his goods?","qvi":"Ông Greaves nhận hàng ngày nào?","opts":["On September 23","On September 25","On September 26","On September 27"],"ans":"B","xp":"Phiếu: 'Scheduled delivery date: September 26'; e-mail: 'receive my chairs a day earlier than scheduled' → 25/9 → (B)."}]}]}};
